1	import "server-only";
2	import { notFound } from "next/navigation";
3	import { db } from "@/lib/db";
4	import { getSetting } from "@/lib/settings";
5	import { FREEMC_GAME_TYPES } from "@/lib/free-minecraft-control";
6	import { APP_URL } from "@/components/marketing/StructuredData";
7	import { loadDirectory } from "@/lib/server-directory-data";
8	import { balanceByContinent } from "@/lib/geo-continent";
9	import { groupByGame, pickFeatured, indexableGamePage, type DirEntry } from "@/lib/server-directory";
10	import { btn } from "./cards";
11	import { esc, nxmHref, type NxmLoad } from "./lib";
12	import { gameArt, gameName, gameRoute, isGameFamily, staged } from "./games-lib";
13	import { supportLine } from "./products-common";
14	import { steamAttributionHtml, steamLogoPresent } from "@/lib/directory-steam";
15	import { providerAttributionHtml } from "@/lib/directory-ingest/providers/registry";
16	
17	/**
18	 * The public server directory — three views of one template:
19	 *
20	 * - /servers (view "free"): free Minecraft servers whose owner made them
21	 *   public (FreeMinecraftServer isPublic + READY), newest first, capped at 48;
22	 *   each links to its own page (/servers/<subdomain>).
23	 * - /game-servers/directory (view "all"): the homepage. A Featured shelf, a
24	 *   cover tile per game that has listings, then the best servers across all
25	 *   games (image first, Nxeon-hosted next, busiest after).
26	 * - /game-servers/directory/<game> (view "game"): every server for one game.
27	 *   Indexable only when enough described, recently seen servers back it
28	 *   (lib/server-directory.ts indexableGamePage); empty or thin pages are noindex.
29	 *
30	 * Sources (lib/server-directory-data.ts): customers' paid servers that opted
31	 * in, free Minecraft servers that opted in, Nxeon community servers and — only
32	 * when an admin enabled it — servers ingested from the Steam list. Nxeon-hosted
33	 * entries wear the Nxeon badge; duplicates by domain / ip / ip:port collapse
34	 * (see lib/server-directory.ts for the exact rule).
35	 *
36	 * No live player counts are probed here (one network round trip per listed
37	 * server on a public page would let one slow host take the directory down):
38	 * counts shown are the community server's own live answer and the figure an
39	 * ingested server had when it was last collected.
40	 */
41	const CAP_HOME = 24;
42	const CAP_GAME = 120;
43	const I = (n: string) => `<span data-au-icon="${n}" data-grad></span>`;
44	
45	async function freeMinecraftEntries(): Promise<{ list: DirEntry[]; modes: string[]; domain: string }> {
46	  const [domain, rows] = await Promise.all([
47	    getSetting("free_minecraft_domain", "play.nxeon.cloud"),
48	    db.freeMinecraftServer.findMany({
49	      where: { isPublic: true, status: "READY" }, orderBy: { createdAt: "desc" }, take: 48,
50	      select: { subdomain: true, name: true, activeGameType: true, publicTagline: true },
51	    }),
52	  ]);
53	  const presetOf = (t: string) => FREEMC_GAME_TYPES[t] ?? FREEMC_GAME_TYPES.vanilla;
54	  return {
55	    domain,
56	    modes: rows.map((s) => `mc-${s.activeGameType}`),
57	    list: rows.map((s): DirEntry => {
58	      const host = `${s.subdomain}.${domain}`;
59	      return {
60	        key: `f-${s.subdomain}`, source: "nxeon-free", nxeon: true, game: "minecraft",
61	        name: s.name || s.subdomain, tagline: s.publicTagline ?? "", description: presetOf(s.activeGameType).description,
62	        imageUrl: null, address: host, host, port: null, alsoKeys: [], players: null, maxPlayers: null,
63	        country: null, region: presetOf(s.activeGameType).label, featured: false,
64	        href: `/servers/${s.subdomain}`, websiteUrl: null, seenAt: null,
65	      };
66	    }),
67	  };
68	}
69	
70	const pad = (n: number) => String(n).padStart(2, "0");
71	/** "2026-10-04 14:05 UTC": a stable absolute time in the markup; page.js turns it into "12 min ago" in the browser. */
72	const utcStamp = (ms: number) => { const d = new Date(ms); return `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())} ${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())} UTC`; };
73	
74	/**
75	 * Freshness line for a found-on-a-list server. "Checked" = Nxeon's own direct query got an answer (only that
76	 * is called a check); "Seen on the list" = the list had it when we last refreshed (no check yet). Nxeon-hosted
77	 * entries carry neither (their numbers are live or absent).
78	 */
79	export function freshnessHtml(e: DirEntry): string {
80	  if (e.checkedAt) return `<time class="dr-chk" datetime="${new Date(e.checkedAt).toISOString()}" data-kind="Checked">Checked ${utcStamp(e.checkedAt)}</time>`;
81	  if (e.attribution && e.seenAt) return `<time class="dr-chk" datetime="${new Date(e.seenAt).toISOString()}" data-kind="Seen on the list">Seen on the list ${utcStamp(e.seenAt)}</time>`;
82	  return "";
83	}
84	
85	/** The Valve/Steam attribution block, only when some listed server's data came from the Steam list. */
86	export function attributionFor(list: DirEntry[]): string {
87	  const steam = list.some((e) => e.attribution === "steam") ? steamAttributionHtml({ logo: steamLogoPresent() }) : "";
88	  const others = [...new Set(list.map((e) => e.attribution).filter((k): k is string => !!k && k !== "steam"))]
89	    .map((k) => providerAttributionHtml(k)).join("");
90	  return steam + others;
91	}
92	
93	const filterTokens = (e: DirEntry, mode?: string) =>
94	  [e.nxeon ? "nx" : "ext", e.imageUrl ? "img" : "", mode ?? ""].filter(Boolean).join(" ");
95	
96	/** One listing card (exported for visual checks with sample rows). */
97	export function card(e: DirEntry, opts: { mode?: string } = {}) {
98	  const art = gameArt(e.game).cover;
99	  const q = [e.name, e.tagline, e.description, gameName(e.game), e.address].join(" ").toLowerCase();
100	  const badge = e.nxeon
101	    ? `<span class="dr-badge nx" title="Hosted on Nxeon">${I("shield")}Nxeon</span>`
102	    : `<span class="dr-badge x" title="Found on a public server list">Public list</span>`;
103	  const fresh = freshnessHtml(e);
104	  const meta = [
105	    e.players != null ? `${e.players}${e.maxPlayers ? ` / ${e.maxPlayers}` : ""} playing` : e.maxPlayers ? `Up to ${e.maxPlayers} players` : "",
106	    e.region ?? "", e.country ?? "",
107	  ].filter(Boolean);
108	  const head = e.imageUrl
109	    ? `<div class="dr-banner"><img src="${esc(e.imageUrl)}" alt="" loading="lazy" decoding="async" referrerpolicy="no-referrer" width="640" height="320"></div>`
110	    : "";
111	  const site = e.websiteUrl ? `<a class="dr-go" href="${esc(e.websiteUrl)}" rel="ugc nofollow noopener noreferrer" target="_blank">Website <span aria-hidden="true">↗</span></a>` : "";
112	  return `<article class="au-card dr-card${e.imageUrl ? " has-img" : ""}" data-q="${esc(q)}" data-f="${esc(filterTokens(e, opts.mode))}">`
113	    + head
114	    + `<div class="dr-top">${art ? `<img class="dr-ic" src="${esc(art)}" alt="" width="46" height="62" loading="lazy">` : ""}<div><h3 title="${esc(e.name)}">${esc(e.name)}</h3><span class="dr-mode">${esc(gameName(e.game))}</span></div>${badge}</div>`
115	    + (e.tagline ? `<p class="dr-tag">${esc(e.tagline)}</p>` : "")
116	    + (e.description ? `<p class="dr-desc">${esc(e.description)}</p>` : "")
117	    + (meta.length ? `<div class="dr-meta">${meta.map((m) => `<span>${esc(m)}</span>`).join("")}</div>` : "")
118	    + (fresh ? `<p class="dr-fresh">${fresh}</p>` : "")
119	    + `<div class="dr-addr"><code title="${esc(e.address)}">${esc(e.address)}</code><button type="button" class="dr-copy" data-copy="${esc(e.address)}">Copy</button></div>`
120	    + (e.href ? `<a class="dr-go" href="${esc(nxmHref(e.href))}">${e.source === "nxeon-community" ? "How to join" : "View server"} <span aria-hidden="true">→</span></a>` : "")
121	    + site
122	    + `</article>`;
123	}
124	
125	function featuredSection(list: DirEntry[]): string {
126	  const f = pickFeatured(list, 6);
127	  if (!f.length) return "";
128	  return `<section class="section dr-feat" id="featured" aria-labelledby="ft-title" style="padding-bottom:0"><div class="container">`
129	    + `<div class="gp-head"><div><h2 class="h2" id="ft-title">Featured servers</h2><p class="lede">Hosted on Nxeon. Servers with a picture and the ones we run ourselves come first.</p></div></div>`
130	    + `<div class="dr-grid dr-grid-feat">${f.map((e) => card(e)).join("")}</div></div></section>`;
131	}
132	
133	function gameTiles(list: DirEntry[]): string {
134	  const groups = groupByGame(list);
135	  if (!groups.length) return "";
136	  return `<div class="dr-games" role="list">` + groups.map((g) => {
137	    const art = gameArt(g.game).cover;
138	    return `<a class="dr-game" role="listitem" href="${esc(nxmHref(`/game-servers/directory/${g.game}`))}">`
139	      + (art ? `<img src="${esc(art)}" alt="" loading="lazy" width="120" height="160">` : `<span class="dr-game-ph" aria-hidden="true"></span>`)
140	      + `<span class="dr-game-t"><b>${esc(gameName(g.game))}</b><small>${g.total} server${g.total === 1 ? "" : "s"}${g.nxeon ? ` · ${g.nxeon} on Nxeon` : ""}</small></span></a>`;
141	  }).join("") + `</div>`;
142	}
143	
144	const SEARCH = `<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></svg>`;
145	
146	function tools(n: number, chips: { f: string; label: string; n: number }[]): string {
147	  if (!n) return "";
148	  const c = chips.length > 1
149	    ? `<div class="dr-chips" role="group" aria-label="Filter"><button type="button" data-f="" aria-pressed="true">All<b>${n}</b></button>${chips.map((x) => `<button type="button" data-f="${esc(x.f)}" aria-pressed="false">${esc(x.label)}<b>${x.n}</b></button>`).join("")}</div>`
150	    : "";
151	  return `<div class="dr-tools"><label class="dr-search">${SEARCH}<span class="visually-hidden">Search servers</span><input id="dr-q" type="search" placeholder="Search by name, game or address" autocomplete="off"></label>${c}<p class="dr-count" id="dr-count" aria-live="polite">${n} server${n === 1 ? "" : "s"}</p></div>`;
152	}
153	
154	const hostCta = (game?: string) => {
155	  const route = game ? gameRoute(game) : null;
156	  return btn(true, route ? staged(route) : nxmHref("/game-servers"), game && route ? `Host your own ${gameName(game)} server` : "Host your own server")
157	    + `<a class="nxm-glassbtn" href="${esc(nxmHref("/free-minecraft"))}"><span class="nxm-bt">Try a free Minecraft server</span></a>`;
158	};
159	
160	const HOW_TO_LIST = [
161	  ["Run your server on Nxeon", "Order a game server, or create a free Minecraft one. Listing is for servers hosted here."],
162	  ["Switch on the Public Directory", "Open your server's Settings tab, turn the Public Directory card on and add a short description. Add a picture and link if you like; we review those before they show."],
163	  ["Players find you here", "A listed server appears with the Nxeon badge while it is running. You can switch it off at any time and it leaves the directory straight away."],
164	];
165	
166	const FAQ_COMMON: [string, string][] = [
167	  ["Do I need an account to join a server?", "No. Copy a server's address and connect from the game. You only need an account to run a server of your own."],
168	  ["What does the Nxeon badge mean?", "The server is hosted on Nxeon. Entries without it come from public server lists and are shown as found: we do not run them."],
169	  ["How is the list ordered?", "Servers with a picture first, then servers hosted on Nxeon, then the busiest. Nothing is paid for: nobody can buy a position."],
170	  ["Where do the servers without the badge come from, and how fresh are they?", "They were found on public server lists (some through the Steam server list). Nxeon then checks each one directly and only lists servers that answered; a card says when it was last checked, and a server that stops answering drops off. Nxeon does not run these servers, and they are not run, hosted or endorsed by Valve or Steam."],
171	  ["Why is a server not in the list?", "Only servers whose owner chose to be listed appear, and a server that stops answering drops off. Servers on other lists are included only when they are public and were seen recently."],
172	  ["Are server addresses safe to share?", "Nxeon-hosted listings show their play address, never a raw IP of ours, and leave the directory the moment the owner switches listing off."],
173	  ["How do I list my own server here?", "Host it on Nxeon, then switch on the Public Directory card in the game panel's Settings tab and add a short description. Free Minecraft servers have the same switch in their Manage tab. You can also copy a ready-made blurb there to submit your server to other public lists."],
174	];
175	
176	const steps = (rows: string[][]) => rows.map(([h, t], i) => `<li class="au-card"><span class="n">0${i + 1}</span><h3>${esc(h)}</h3><p>${esc(t)}</p></li>`).join("");
177	const faqHtml = (rows: [string, string][]) => rows.map(([q, a], i) => `<details${i === 0 ? " open" : ""}><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join("");
178	
179	export async function load(p: Record<string, string>): Promise<NxmLoad> {
180	  const view = p.view === "all" ? "all" : p.view === "free" ? "free" : p.view === "game" ? "game" : null;
181	  if (!view) notFound();
182	
183	  // ── /servers: free Minecraft, behaviour unchanged ────────────────────────
184	  if (view === "free") {
185	    const { list, domain } = await freeMinecraftEntries();
186	    const n = list.length;
187	    const modes = new Map<string, { label: string; n: number }>();
188	    for (const e of list) {
189	      const f = `mc-${e.region}`;
190	      modes.set(f, { label: e.region ?? "", n: (modes.get(f)?.n ?? 0) + 1 });
191	    }
192	    const createFree = btn(true, "/dashboard/free-minecraft", "Create my free server");
193	    const empty = `<div class="au-card dr-empty"><span class="au-tile">${I("server")}</span><h3>No public servers yet</h3><p>Be the first: create a free server and turn on public listing from its Manage tab.</p>${createFree}</div>`;
194	    const faq: [string, string][] = [
195	      ["Do I need an account to join a server?", "No. Copy a server's address and connect from Minecraft. You only need an account to run a server of your own."],
196	      ["How do I list my own server here?", "Create a free Minecraft server, then turn on public listing from its Manage tab. It appears here as soon as it's ready."],
197	      ["How is the list ordered?", "Newest first. Nothing here is curated or ranked; names, taglines and game modes come from each server's owner."],
198	      ["Why does a free server take a moment to respond?", "Free servers sleep when nobody is playing. Connecting wakes the server up, and it's back within seconds."],
199	      ["Are server addresses safe to share?", "Every listing shows a subdomain, never a raw IP address, and a server leaves the directory the moment its owner turns listing off."],
200	    ];
201	    return {
202	      slots: {
203	        "hero.chip": "Public directory", "hero.h1a": "Public Minecraft servers.", "hero.h1b": "Pick one, connect now.",
204	        "hero.sub": "Every server below is a real free Nxeon server whose owner opted in to be listed. No account needed to join: copy the address and connect.",
205	        "hero.ctas:html": createFree + `<a class="nxm-glassbtn" href="${esc(nxmHref("/game-servers"))}"><span class="nxm-bt">Need more power? See paid servers</span></a>`,
206	        "facts:html": `<li>${I("server")}<b>${n}</b> listed now</li><li>${I("globe")}Addresses on <b>*.${esc(domain)}</b></li><li>${I("users")}No account needed to join</li>`,
207	        "featured:html": "",
208	        "list.h": "Browse the directory", "list.lede": "Owner-submitted taglines and game modes. Nothing here is curated or ranked, just newest first.",
209	        "games:html": "",
210	        "tools:html": tools(n, [...modes].sort((a, b) => b[1].n - a[1].n).map(([f, g]) => ({ f, label: g.label, n: g.n }))),
211	        "grid:html": n ? list.map((e) => card(e, { mode: `mc-${e.region}` })).join("") : empty,
212	        "attribution:html": "",
213	        "steps.h": "List your own server here", "steps.lede": "Owners choose to be listed, and can switch it off at any time.",
214	        "steps:html": steps([
215	          ["Create a free server", `No credit card. Pick a name and it's live at yourworld.${domain}.`],
216	          ["Turn on public listing", "Open your server's Manage tab, switch public listing on and add a tagline."],
217	          ["Players find you here", "Your server appears in this directory as soon as it's ready, its address one click from copied."]]),
218	        "faq.lede": supportLine(),
219	        "faq:html": faqHtml(faq),
220	        "final.h": "Get your own free Minecraft server",
221	        "final.p": "No credit card, live in under a minute, and you can list it here the moment it's ready.",
222	        "final:html": createFree + `<a class="nxm-glassbtn" href="${esc(nxmHref("/free-minecraft"))}"><span class="nxm-bt">Learn how it works</span></a>`,
223	      },
224	      jsonLd: n ? [{
225	        "@context": "https://schema.org", "@type": "CollectionPage", name: "Public Minecraft server directory", url: `${APP_URL}/servers`,
226	        mainEntity: { "@type": "ItemList", numberOfItems: n, itemListElement: list.slice(0, 48).map((e, i) => ({ "@type": "ListItem", position: i + 1, name: e.name, url: `${APP_URL}/servers/${e.address.split(".")[0]}` })) },
227	      }] : [],
228	      crumb: "Server directory",
229	    };
230	  }
231	
232	  // ── all games / one game ─────────────────────────────────────────────────
233	  const gameKey = view === "game" ? String(p.game ?? "").toLowerCase() : "";
234	  if (view === "game" && !isGameFamily(gameKey)) notFound();
235	  const { entries } = await loadDirectory(view === "game" ? { game: gameKey } : {});
236	  const list = entries;
237	  const nx = list.filter((e) => e.nxeon).length;
238	  const withImg = list.filter((e) => e.imageUrl).length;
239	  const gamesN = new Set(list.map((e) => e.game)).size;
240	  // A game page lists up to CAP_GAME servers: Nxeon-hosted ones always, the rest shared fairly between continents
241	  // (the ranked top-N alone is whichever region is busiest). The homepage shelf keeps the plain ranked top.
242	  const shown = view === "game"
243	    ? (() => { const nxe = list.filter((e) => e.nxeon); return [...nxe, ...balanceByContinent(list.filter((e) => !e.nxeon), (e) => e.country, Math.max(0, CAP_GAME - nxe.length))]; })()
244	    : list.slice(0, CAP_HOME);
245	  const gname = view === "game" ? gameName(gameKey) : "";
246	  const chips = [
247	    { f: "nx", label: "Hosted on Nxeon", n: shown.filter((e) => e.nxeon).length },
248	    { f: "ext", label: "Public lists", n: shown.filter((e) => !e.nxeon).length },
249	    { f: "img", label: "With picture", n: shown.filter((e) => e.imageUrl).length },
250	  ].filter((c) => c.n > 0 && c.n < shown.length);
251	
252	  const empty = `<div class="au-card dr-empty"><span class="au-tile">${I("server")}</span><h3>${view === "game" ? `No ${esc(gname)} servers listed yet` : "No servers listed yet"}</h3><p>${view === "game" ? `Be the first to list a ${esc(gname)} server here.` : "Be the first to list your server in the directory."}</p>${hostCta(view === "game" ? gameKey : undefined)}</div>`;
253	
254	  const facts = `<li>${I("server")}<b>${list.length}</b> listed now</li>`
255	    + (nx ? `<li>${I("shield")}<b>${nx}</b> hosted on Nxeon</li>` : "")
256	    + (withImg ? `<li>${I("spark")}<b>${withImg}</b> with a picture</li>` : "")
257	    + (view === "all" && gamesN > 1 ? `<li>${I("game")}<b>${gamesN}</b> games</li>` : "")
258	    + `<li>${I("users")}No account needed to join</li>`;
259	
260	  const route = view === "game" ? `/game-servers/directory/${gameKey}` : "/game-servers/directory";
261	  const itemList = list.length ? [{
262	    "@context": "https://schema.org", "@type": "CollectionPage",
263	    name: view === "game" ? `${gname} server directory` : "Public game server directory", url: APP_URL + route,
264	    mainEntity: { "@type": "ItemList", numberOfItems: list.length, itemListElement: shown.slice(0, 48).map((e, i) => ({ "@type": "ListItem", position: i + 1, name: e.name })) },
265	  }] : [];
266	
267	  return {
268	    slots: {
269	      "hero.chip": view === "game" ? `${gname} directory` : "Server directory",
270	      "hero.h1a": view === "game" ? `${gname} servers` : "Find a server,",
271	      "hero.h1b": view === "game" ? "to join right now." : "join in one click.",
272	      "hero.sub": view === "game"
273	        ? `Public ${gname} servers: the ones hosted on Nxeon and others found on public server lists. Copy an address and connect.`
274	        : "Community servers across every game, hosted on Nxeon and found on public lists. Pick a game, copy the address, and start playing.",
275	      "hero.ctas:html": hostCta(view === "game" ? gameKey : undefined),
276	      "facts:html": facts,
277	      "featured:html": featuredSection(list),
278	      "list.h": view === "game" ? `All ${gname} servers` : "Browse by game",
279	      "list.lede": view === "game"
280	        ? "Servers with a picture first, then servers hosted on Nxeon, then the busiest."
281	        : "Pick a game, or search every server below. Servers with a picture come first.",
282	      "games:html": view === "all" ? gameTiles(list) : "",
283	      "tools:html": tools(shown.length, chips),
284	      "grid:html": shown.length ? shown.map((e) => card(e)).join("") : empty,
285	      "attribution:html": attributionFor(list),
286	      "steps.h": "List your own server here",
287	      "steps.lede": "Owners choose to be listed, and can switch it off at any time.",
288	      "steps:html": steps(HOW_TO_LIST),
289	      "faq.lede": supportLine(),
290	      "faq:html": faqHtml(FAQ_COMMON),
291	      "final.h": view === "game" ? `Host your own ${gname} server` : "Host your own server",
292	      "final.p": "Get a game server with a control panel, backups and mods, then list it here for others to find.",
293	      "final:html": hostCta(view === "game" ? gameKey : undefined),
294	    },
295	    jsonLd: itemList,
296	    crumb: view === "game" ? gname : "Server directory",
297	    trail: view === "game" ? [{ name: "Server directory", path: "/game-servers/directory" }] : undefined,
298	  };
299	}
300	
301	export async function meta(p: Record<string, string>) {
302	  if (p.view === "free") return { image: gameArt("minecraft").hero ?? undefined };
303	  if (p.view === "all") {
304	    return {
305	      title: "Public Game Server Directory",
306	      description: "Browse public game servers: Minecraft, Valheim, Project Zomboid and more. Servers hosted on Nxeon carry a badge. Pick a game, copy the address and connect.",
307	      image: gameArt("minecraft").hero ?? undefined,
308	    };
309	  }
310	  if (p.view !== "game") notFound();
311	  const game = String(p.game ?? "").toLowerCase();
312	  if (!isGameFamily(game)) notFound();
313	  const { entries } = await loadDirectory({ game });
314	  const name = gameName(game);
315	  return {
316	    title: `${name} Server List: Public ${name} Servers to Join`,
317	    description: entries.length
