      country: null, region: c.region ? customerRegionLabel(c.region) : null, featured: true,
      href: `/free-${c.game}-server`, websiteUrl: null, seenAt: l.state === "online" ? l.checkedAt : null,
    };
  }));
}

/** Drops external rows whose connection address shows another game host. Pure; `rules` null = no filtering. */
export function filterExternalRows<T extends { host: string; port: number; ptrName?: string | null }>(rows: T[], rules: RuleSet | null): T[] {
  if (!rules) return rows;
  return rows.filter((r) => !isRowBlocked({ host: r.host, port: r.port, ptrName: r.ptrName ?? null }, rules));
}

/**
 * Liveness filter for stored external rows. Pure. DEAD rows never show. With the prober ON a row must have
 * answered our own direct check in the last 24 h (nothing unverified is presented as live); with it OFF the
 * Steam list alone decides and the card says "seen on the list", never "checked".
 */
export function filterLiveRows<T extends { probeStatus: string; lastAliveAt: Date | null; lastSeenAt: Date }>(rows: T[], probeOn: boolean, now = Date.now()): T[] {
  return rows.filter((r) => isRowPublic(r, { probeOn, now }));
}

/** Most third-party rows one directory load returns, shared fairly between continents (see balanceByContinent). */
export const EXTERNAL_TOTAL = 1000;
/** Raw rows read per continent bucket before the blocklist/liveness filters (headroom so filtering still leaves a fair share). */
export const EXTERNAL_FETCH_PER_BUCKET = 400;

/** Players desc (unknown last), then name: the order the directory has always shown. Pure. */
export function byPlayersThenName<T extends { players: number | null; name: string }>(rows: T[]): T[] {
  return [...rows].sort((a, b) => (b.players ?? -1) - (a.players ?? -1) || a.name.localeCompare(b.name));
}

/** Region-balanced pick of external rows: best-first order is kept, but every continent present gets a fair share. Pure. */
export function pickBalancedExternal<T extends { players: number | null; name: string; country: string | null }>(rows: T[], total = EXTERNAL_TOTAL): T[] {
  return balanceByContinent(byPlayersThenName(rows), (r) => r.country, total);
}

async function externalEntries(game?: string): Promise<DirEntry[]> {
  if (!(await safe(getSettingBool("directory_external_show", false), false))) return [];
  const probeOn = await safe(getSettingBool("directory_probe_enabled", false), false);
  const base = { hidden: false, blockedReason: null, probeStatus: probeOn ? "ALIVE" : { not: "DEAD" }, lastSeenAt: { gte: new Date(Date.now() - 3 * 86_400_000) }, ...(game ? { game } : {}) } satisfies Prisma.ExternalServerWhereInput;
  const orderBy: Prisma.ExternalServerOrderByWithRelationInput[] = [{ players: { sort: "desc", nulls: "last" } }, { name: "asc" }];
  // One query per continent (by the stored ISO-2 country) plus one for rows with no/unknown country. A single
  // "top N by players" query is all one continent, because the Steam list answers nearest-to-us first.
  const known = CONTINENT_ORDER.flatMap((c) => countriesOf(c));
  const withBoth = (c: Continent) => countriesOf(c).flatMap((x) => [x, x.toLowerCase()]);
  const buckets: Prisma.ExternalServerWhereInput[] = [
    ...CONTINENT_ORDER.map((c) => ({ country: { in: withBoth(c) } })),
    { OR: [{ country: null }, { country: { notIn: known.flatMap((x) => [x, x.toLowerCase()]) } }] },
  ];
  const parts = await Promise.all(buckets.map((b) => safe(db.externalServer.findMany({
    where: { ...base, ...b }, orderBy, take: EXTERNAL_FETCH_PER_BUCKET,
  }), [])));
  const rawRows = parts.flat();
  // Competitor-host blocklist, re-run on every read against the CURRENT rules: a rule an admin just
  // added hides already-ingested rows at once, with no re-ingest. (blockedReason: null above is the
  // stored verdict; this is the live one. No network: PTR names were stored at ingest time.)
  const rules = await safe(loadRuleSet().then((r) => r.set), buildRuleSet().set); // default list still applies if settings can't be read
  const now = Date.now();
  const rows = pickBalancedExternal(filterLiveRows(filterExternalRows(rawRows, rules), probeOn, now));
  return rows.map((r): DirEntry => ({
    key: `x-${r.id.slice(0, 10)}`, source: "external", nxeon: false, game: r.game,
    name: r.name, tagline: "", description: r.description ?? (r.map ? `Map: ${r.map}` : ""),
    imageUrl: r.imageUrl, address: `${r.host}:${r.port}`, host: r.host, port: r.port,
    alsoKeys: r.ipKey ? [r.ipKey] : [],
    // A count is only shown as "playing now" while its newest source is under an hour old.
    players: liveCountsFresh(r, now) ? r.players : null, maxPlayers: r.maxPlayers, country: r.country, region: null, featured: false,
    href: null, websiteUrl: null, seenAt: r.lastSeenAt.getTime(),
    attribution: r.attribution ?? (r.source === "valve" ? "steam" : null), // "Checked" means OUR direct query answered; a listing source's heartbeat is not that, so those rows say "seen on the list".
    checkedAt: r.lastAliveAt && r.probeKind !== "listing" ? r.lastAliveAt.getTime() : null,
  }));
}

/** Every Nxeon-hosted entry (all games), before dedupe. Also used by the ingester to avoid re-listing our own servers. */
export async function nxeonEntries(): Promise<DirEntry[]> {
  const [paid, free, comm] = await Promise.all([paidEntries(), freeMcEntries(), communityEntries()]);
  return [...paid, ...free, ...comm];
}

/** The ip:port / host:port keys of everything Nxeon hosts (for ingest-time dedupe). */
export async function nxeonConnectionKeys(): Promise<Set<string>> {
  const out = new Set<string>();
  for (const e of await nxeonEntries()) {
    out.add(connKey(e.game, e.host, e.port));
    for (const k of e.alsoKeys) out.add(k);
  }
  return out;
}

/** Merged, deduplicated, ranked directory. `game` narrows to one family. */
export async function loadDirectory(opts: { game?: string } = {}): Promise<{ entries: DirEntry[]; dropped: number }> {
  const [nx, ext] = await Promise.all([nxeonEntries(), externalEntries(opts.game)]);
  const all = [...nx, ...ext].filter((e) => !opts.game || e.game === opts.game);
  const { entries, dropped } = dedupeEntries(all);
  return { entries: rankEntries(entries), dropped };
}

