const EXCLUDE = new Set<string>(["/blog/how-to-self-host-vaultwarden-behind-an-nginx-reverse-proxy"]);

export type SectionId = string; // core | games | game-locations | locations | compare | blog | tools | servers | mods-N

/** Which section a plain marketing path belongs to. */
export function sectionForPath(path: string): SectionId {
  const p = path.replace(/\/+$/, "") || "/";
  if (p.startsWith("/blog")) return "blog";
  if (p.startsWith("/tools")) return "tools";
  if (p.startsWith("/servers")) return "servers";
  if (p.startsWith("/mods")) return "core";
  if (/^\/vps-vs-|-alternative$|^\/migrate-from-|^\/compare/.test(p)) return "compare";
  if (/^\/[^/]+-server-hosting\/[^/]+$/.test(p)) return "game-locations";
  if (GAME_LOCATION_SET.has(p.slice(1))) return "game-locations";
  if (LOCATION_SET.has(p.slice(1))) return "locations";
  if (/-server-hosting$|^\/plutonium-|^\/game-servers|^\/gaming-vps$|^\/free-minecraft$/.test(p)) return "games";
  return "core";
}

const GAME_LOCATION_SET = new Set<string>(GAME_LOCATION_SLUGS);
const LOCATION_SET = new Set<string>([...LANDING_SLUGS, ...REGION_LANDING_SLUGS, ...GENERAL_LOCATION_SLUGS]);

const normPath = (p: string) => (p === "/" ? "/" : p.replace(/\/+$/, ""));
const abs = (p: string) => `${APP_URL}${p === "/" ? "/" : p}`;

/** Every non-row-backed URL, deduplicated, bucketed by section. No dates (see header). */
export function staticSections(): Map<SectionId, SitemapEntry[]> {
  const out = new Map<SectionId, SitemapEntry[]>();
  const seen = new Set<string>();
  const add = (path: string) => {
    const p = normPath(path);
    if (EXCLUDE.has(p) || seen.has(p)) return;
    seen.add(p);
    const sec = sectionForPath(p);
    if (!out.has(sec)) out.set(sec, []);
    out.get(sec)!.push({ url: abs(p) });
  };
  for (const p of STATIC_PATHS) add(p);
  for (const s of [...LANDING_SLUGS, ...REGION_LANDING_SLUGS, ...GAME_LOCATION_SLUGS, ...GENERAL_LOCATION_SLUGS]) add(`/${s}`);
  for (const t of TOOL_SLUGS) add(`/tools/${t}`);
  add("/mods");
  // Pages that exist only on the new marketing site (app/nxm): every exact route it serves.
  // (individual mod pages are listed from the database by the mods-N sections — don't also list them here)
  if (process.env.NXM_ROOT === "1") for (const r of NXM_LIVE_ROUTES.exact) if (!/^\/mods\/[^/]+\/[^/]+$/.test(r) || r.startsWith("/mods/games/")) add(r);
  return out;
}

/** staticSections() minus game × location combos the index policy keeps out of the sitemap (lib/seo-index-policy.ts). */
async function policedStaticSections(): Promise<Map<SectionId, SitemapEntry[]>> {
  const st = staticSections();
  const gl = st.get("game-locations");
  if (gl) {
    const kept: SitemapEntry[] = [];
    for (const e of gl) {
      const slug = e.url.slice(APP_URL.length + 1);
      if (!GAME_LOCATION_SET.has(slug) || (await listGameLocationInSitemap(slug))) kept.push(e);
    }
    st.set("game-locations", kept);
  }
  // Community-server pages (/free-<game>-server) exist only while an admin has the server LIVE; a route
  // that would 404 must not be advertised to crawlers. If the lookup fails, advertise none of them.
  const live = new Set<string>();
  try {
    for (const c of await listVisibleFreePublicServers()) live.add(`/free-${c.game}-server`);
  } catch {
    /* keep empty */
  }
  for (const [sec, list] of st) {
    st.set(sec, list.filter((e) => {
      const path = e.url.slice(APP_URL.length) || "/";
      return !/^\/free-[a-z0-9]+-server$/.test(path) || live.has(path);
    }));
  }
  return st;
}

export interface SectionInfo {
  id: SectionId;
  count: number;
  lastmod?: Date;
}

let cache: { at: number; sections: SectionInfo[] } | null = null;

/** Section list for the index and for generateSitemaps(). Cached 5 minutes. */
export async function listSections(): Promise<SectionInfo[]> {
  if (cache && Date.now() - cache.at < 5 * 60_000) return cache.sections;
  const order = ["core", "games", "game-locations", "locations", "compare", "tools"];
  const st = await policedStaticSections();
  const sections: SectionInfo[] = order.filter((id) => st.has(id)).map((id) => ({ id, count: st.get(id)!.length }));

  try {
    const blog = await db.blogPost.aggregate({ where: { published: true, slug: { notIn: [...REDIRECTED_BLOG_SLUGS] } }, _count: true, _max: { updatedAt: true } });
    if (blog._count) sections.push({ id: "blog", count: blog._count + (st.get("blog")?.length ?? 0), lastmod: blog._max.updatedAt ?? undefined });
  } catch {
    if (st.has("blog")) sections.push({ id: "blog", count: st.get("blog")!.length });
  }
  try {
    const srv = await db.freeMinecraftServer.aggregate({ where: { isPublic: true, status: "READY" }, _count: true, _max: { createdAt: true } });
    sections.push({ id: "servers", count: srv._count + (st.get("servers")?.length ?? 0), lastmod: srv._max.createdAt ?? undefined });
  } catch {
    if (st.has("servers")) sections.push({ id: "servers", count: st.get("servers")!.length });
  }
  const pol = await loadSeoPolicy();
  const chunks = modChunkCountFor(await countIndexableMods(pol.modSitemapMinDownloads));
  for (let i = 1; i <= chunks; i++) sections.push({ id: `mods-${i}`, count: -1 });
  cache = { at: Date.now(), sections };
  return sections;
}

/** The URLs of one section. */
export async function sectionEntries(id: SectionId): Promise<SitemapEntry[]> {
  const st = await policedStaticSections();
  if (id.startsWith("mods-")) {
    const n = Number(id.slice(5));
    if (!Number.isInteger(n) || n < 1) return [];
    const rows = await listIndexableModSlugsChunk(n - 1, (await loadSeoPolicy()).modSitemapMinDownloads);
    return rows.map((m) => ({ url: `${APP_URL}/mods/${m.family}/${m.slug}`, lastModified: m.lastModified }));
  }
  const entries = [...(st.get(id) ?? [])];
  if (id === "core") {
    // Modpack server pages (growth seo-029/prd-034): listed only while modpack_pages_enabled is on.
    try {
      for (const slug of await modpackSitemapSlugs()) entries.push({ url: `${APP_URL}/modpacks/${slug}` });
    } catch {
      /* catalogue unavailable: advertise none */
    }
  }
  if (id === "blog") {
    try {
      const posts = await db.blogPost.findMany({ where: { published: true, slug: { notIn: [...REDIRECTED_BLOG_SLUGS] } }, select: { slug: true, updatedAt: true }, orderBy: { publishedAt: "desc" } });
      const seen = new Set(entries.map((e) => e.url));
      for (const p of posts) {
        const url = `${APP_URL}/blog/${p.slug}`;
        if (REDIRECTED_BLOG_SLUGS.has(p.slug)) continue; // 301s elsewhere — never advertise a redirect
        if (!seen.has(url)) entries.push({ url, lastModified: p.updatedAt });
      }
    } catch {
      /* blog table unavailable */
    }
  }
  if (id === "servers") {
    try {
      const rows = await db.freeMinecraftServer.findMany({ where: { isPublic: true, status: "READY" }, select: { subdomain: true, createdAt: true } });
      const seen = new Set(entries.map((e) => e.url));
      for (const s of rows) {
        const url = `${APP_URL}/servers/${s.subdomain}`;
        if (!seen.has(url)) entries.push({ url, lastModified: s.createdAt });
      }
    } catch {
      /* table unavailable */
    }
    // Per-game directory pages (seo-025): advertised only when enough described,
    // recently seen servers back the page (indexableGamePage) — thin ones stay noindex.
    try {
      const { entries: dir } = await loadDirectory();
      const byGame = new Map<string, typeof dir>();
      for (const e of dir) (byGame.get(e.game) ?? byGame.set(e.game, []).get(e.game)!).push(e);
      const seen = new Set(entries.map((e) => e.url));
      for (const [game, list] of byGame) {
        const url = `${APP_URL}/game-servers/directory/${game}`;
        if (indexableGamePage(list) && !seen.has(url)) entries.push({ url });
      }
    } catch {
      /* directory unavailable */
    }
  }
  return entries;
}
