/* Throwaway seed for the directory hub dev DB (NOT committed). Usage: DATABASE_URL=... npx tsx .dirhub-seed.ts [scale] */
import { PrismaClient } from "@prisma/client";
import crypto from "node:crypto";

const db = new PrismaClient();
const scale = Number(process.argv[2] ?? 1);
let seed = 42;
const rnd = () => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed / 2147483648; };
const pick = <T,>(a: T[]) => a[Math.floor(rnd() * a.length)];

// country weights: a realistic multi-continent Steam spread after the 8-region fan-out
const CC: [string, number][] = [["US", 22], ["DE", 14], ["GB", 6], ["FR", 6], ["RU", 7], ["PL", 4], ["NL", 4], ["SE", 2], ["FI", 2], ["BR", 7], ["AR", 2], ["CL", 1], ["SG", 9], ["JP", 3], ["KR", 3], ["CN", 4], ["HK", 2], ["TH", 3], ["PH", 2], ["ID", 2], ["AU", 5], ["NZ", 1], ["ZA", 1], ["CA", 4], ["TR", 2], ["UA", 2], ["IN", 1], ["VN", 1]];
const ccPick = () => { const t = CC.reduce((s, [, w]) => s + w, 0); let r = rnd() * t; for (const [c, w] of CC) { if ((r -= w) < 0) return c; } return "US"; };

const NAMES: Record<string, { pre: string[]; core: string[]; maps: string[]; max: number[]; tags: string[] }> = {
  rust: { pre: ["[EU]", "[US]", "[AU]", "Rustoria", "Rusty Moose", "Stevious", "Rustafied", "UKN", "Survivors.gg", "Atlas"], core: ["Main", "2x Monthly", "Vanilla Weekly", "5x No BPs", "Solo/Duo/Trio", "Biweekly | Kits", "Long Term", "Training Grounds"], maps: ["Procedural Map", "Barren", "Hapis Island", "Custom Map"], max: [100, 150, 200, 250, 300, 500], tags: ["mp200", "cp43", "pve", "weekly", "vanilla", "born1790876", "v2634"] },
