  valheim: { pre: ["Viking", "Midgard", "Valhalla", "Nordic", "Odin's", "Yggdrasil", "Ashlands"], core: ["Realm", "Vanilla+", "Hardcore", "Chill PvE", "Community", "Builders", "Mistlands"], maps: ["Dedicated"], max: [10, 10, 10, 64], tags: ["g=0.219.14", "n=4"] },
