  gmod: { pre: ["DarkRP", "TTT", "Prop Hunt", "Sandbox", "Murder", "Jailbreak", "StarWarsRP", "Deathrun"], core: ["| Free VIP", "#1", "| Custom Jobs", "Fun", "Official", "| New Map", "Classic"], maps: ["rp_downtown_v4c", "ttt_minecraft_b5", "gm_construct", "ph_office", "rp_bangclaw"], max: [32, 64, 128], tags: ["gm:darkrp", "gm:terrortown"] },
  tf2: { pre: ["Uncletopia", "Skial", "Blackwonder", "Saxton Hale", "2Fort 24/7", "MvM", "Jump"], core: ["| Seattle", "| Frankfurt", "#3", "Casual", "Fun", "Vanilla", "Nocrits"], maps: ["ctf_2fort", "pl_badwater", "koth_harvest_final", "cp_process_final", "pl_upward"], max: [24, 32, 100], tags: ["nocrits", "increased_maxplayers"] },
  dayz: { pre: ["DayZ Underground", "Rearmed", "Survivor", "Namalsk", "Chernarus+"], core: ["PvE", "Hardcore", "Deathmatch", "Vanilla++", "Trader"], maps: ["chernarusplus", "enoch", "namalsk", "deerisle"], max: [60, 80, 100, 127], tags: [] },
