  squad: { pre: ["[ARMY]", "Bluedrop", "Fishbowl", "[TDN]", "Mercenary"], core: ["| Invasion", "| Seed", "Main", "| New Players Welcome"], maps: ["Narva", "Gorodok", "Yehorivka", "Mutaha"], max: [80, 98, 100], tags: [] },
  ark: { pre: ["ARK", "Tek", "Primal", "Genesis", "Fjordur"], core: ["10x PvP", "PvE Cluster", "Boosted", "Small Tribes", "Official-like"], maps: ["TheIsland", "Ragnarok", "Fjordur", "Valguero_P"], max: [30, 50, 70], tags: [] },
