// Throwaway screenshot helper (NOT committed): node .dirhub-shot.cjs <outPrefix> <path> [<path> ...]
const { chromium } = require("playwright");
(async () => {
  const [prefix, ...paths] = process.argv.slice(2);
  const browser = await chromium.launch();
  for (const p of paths) {
    for (const [w, h] of [[1440, 900], [390, 844]]) {
      const ctx = await browser.newContext({ viewport: { width: w, height: h }, deviceScaleFactor: 1, reducedMotion: "reduce" });
      const page = await ctx.newPage();
      await page.goto("http://localhost:3047" + p, { waitUntil: "networkidle", timeout: 240000 });
      await page.waitForTimeout(800);
      const name = `${prefix}${p.replace(/[^a-z0-9]+/gi, "_").replace(/^_|_$/g, "") || "root"}-${w}.png`;
      await page.screenshot({ path: name, fullPage: true });
      const sw = await page.evaluate(() => document.documentElement.scrollWidth);
      console.log(name, "scrollWidth", sw);
      await ctx.close();
    }
  }
  await browser.close();
})().catch((e) => { console.error(e); process.exit(1); });

