  return SLUG_OF.get(code.trim().toUpperCase()) ?? null;
}
export const continentSlug = (c: Continent) => CONTINENT_SLUG[c];
export const allCountryCodes = (): readonly string[] => ALL_CC;

export type Region =
  | { kind: "continent"; code: Continent; slug: string; label: string }
  | { kind: "country"; code: string; slug: string; label: string; continent: Continent };

export function continentRegion(c: Continent): Region {
  return { kind: "continent", code: c, slug: CONTINENT_SLUG[c], label: CONTINENT_LABELS[c] };
}
export function countryRegion(code: string): Region | null {
  const cc = code.trim().toUpperCase();
  const slug = SLUG_OF.get(cc);
  const cont = continentOf(cc);
  if (!slug || !cont) return null;
  return { kind: "country", code: cc, slug, label: countryName(cc), continent: cont };
}

const ALIASES: Record<string, string> = { uk: "GB", usa: "US", america: "US", "great-britain": "GB", england: "GB", korea: "KR" };

/**
 * Resolve a URL segment. `{ region }` for a canonical slug, `{ redirect }` (the canonical slug) for an
 * alias form (ISO code, different case, "uk"), null for anything unknown.
 */
export function resolveRegionSlug(raw: string): { region: Region } | { redirect: string } | null {
  const s = String(raw ?? "").trim();
  if (!s || s.length > 60) return null;
  const lower = s.toLowerCase();
  const cont = CONTINENT_BY_SLUG.get(lower);
  if (cont) return lower === s ? { region: continentRegion(cont) } : { redirect: lower };
  const cc = CC_BY_SLUG.get(lower);
  if (cc) return lower === s ? { region: countryRegion(cc)! } : { redirect: lower };
  const alias = ALIASES[lower] ?? (/^[a-z]{2}$/.test(lower) && SLUG_OF.has(lower.toUpperCase()) ? lower.toUpperCase() : null);
  if (alias) return { redirect: SLUG_OF.get(alias)! };
  const fuzzy = CC_BY_SLUG.get(slugify(s));
  if (fuzzy) return { redirect: SLUG_OF.get(fuzzy)! };
  return null;
}

/** ISO codes covered by a region (a continent's list, or the one country). Upper-case. */
export function regionCountries(r: Region): string[] {
  return r.kind === "continent" ? countriesOf(r.code) : [r.code];
}

