import { createHash } from "node:crypto";
import { isGameFamily } from "@/lib/directory-games";

/**
 * Public ids for server detail pages: `<game>-<10 hex>`. Never an internal cuid or a database row id.
 *  - third-party rows: the first 10 hex of sha256(connKey) (stable across re-ingest: connKey is the
 *    normalised address). The SQL side computes the same value (lib/directory-query-sql.ts buildByShortId).
 *  - Nxeon-hosted listings: sha256("nx:" + the entry's opaque key), so the two can never collide in meaning.
 */
export const shortHash = (s: string) => createHash("sha256").update(s, "utf8").digest("hex").slice(0, 10);
export const externalServerId = (game: string, connKey: string) => `${game}-${shortHash(connKey)}`;
export const nxeonServerId = (game: string, entryKey: string) => `${game}-${shortHash("nx:" + entryKey)}`;

/** Split a detail id into game + hash; null when malformed or the game is unknown. */
export function parseServerId(raw: string): { game: string; hash: string } | null {
  const m = /^([a-z0-9]{2,20})-([0-9a-f]{10})$/.exec(String(raw ?? "").trim().toLowerCase());
  if (!m || !isGameFamily(m[1])) return null;
  return { game: m[1], hash: m[2] };
}

