/**
 * Server directory aggregate pages: PURE rules (no db, no I/O; unit-tested).
 *
 * Owns: the URL tree, the facet roll-up maths, which pages may be indexed (and so listed in the
 * sitemap), canonical URLs, titles/descriptions, the data-derived intro copy, breadcrumbs and the
 * ItemList structured data. Copy here states only what the numbers say: no adjectives, no claims.
 *
 * Index rules (owner, 2026-10-05):
 *  - directory home and the all-games index: always indexable (they always have content: every game)
 *  - a game page: indexable with >= GAME_INDEX_MIN listings; an empty/thin game page renders
 *    (honest empty state + host CTA) but is noindex and not in the sitemap
 *  - a game + region page: indexable only with >= REGION_INDEX_MIN listings
 *  - page 2+ of a list, and any filtered/searched/sorted variant: noindex,follow, canonical to page 1
 *    for filters (page N keeps a self canonical so its links are still crawled)
 *  - a server detail page: indexable only for Nxeon-hosted servers; third-party servers noindex,follow
 */
import { CONTINENT_LABELS, CONTINENT_ORDER, continentOf, type Continent } from "@/lib/geo-continent";
import { continentRegion, countryName, countryRegion, countrySlug, type Region } from "@/lib/directory-regions";

export const DIR = "/game-servers/directory";
export const GAME_INDEX_MIN = 5;
export const REGION_INDEX_MIN = 10;

export const dirPath = () => DIR;
export const gamesPath = () => `${DIR}/games`;
export const gamePath = (game: string) => `${DIR}/${game}`;
export const regionPath = (game: string, slug: string) => `${DIR}/${game}/${slug}`;
export const serverPath = (id: string) => `${DIR}/server/${id}`;

// ── facets ────────────────────────────────────────────────────────────────
export type FacetRow = { game: string; cc: string | null; n: number; p: number; newest: Date | null };
export type Tally = { n: number; p: number; newest: number };
const zero = (): Tally => ({ n: 0, p: 0, newest: 0 });
const add = (t: Tally, r: { n: number; p: number; newest: Date | null }) => {
  t.n += r.n; t.p += r.p; t.newest = Math.max(t.newest, r.newest ? r.newest.getTime() : 0);
};

export type GameFacet = Tally & { game: string; countries: Map<string, Tally>; continents: Map<Continent, Tally>; unknown: Tally };
export type Facets = { total: Tally; games: Map<string, GameFacet>; countries: Map<string, Tally>; continents: Map<Continent, Tally> };

/** Roll the (game, country) GROUP BY rows up into every count the pages show. */
export function rollUp(rows: FacetRow[]): Facets {
  const out: Facets = { total: zero(), games: new Map(), countries: new Map(), continents: new Map() };
  for (const r of rows) {
    const cc = r.cc ? r.cc.toUpperCase() : null;
    const cont = continentOf(cc);
    let g = out.games.get(r.game);
    if (!g) { g = { game: r.game, ...zero(), countries: new Map(), continents: new Map(), unknown: zero() }; out.games.set(r.game, g); }
    add(g, r); add(out.total, r);
    if (cc && cont) {
      for (const [m, k] of [[g.countries, cc], [out.countries, cc]] as const) { const t = m.get(k) ?? zero(); add(t, r); m.set(k, t); }
      for (const m of [g.continents, out.continents]) { const t = m.get(cont) ?? zero(); add(t, r); m.set(cont, t); }
    } else add(g.unknown, r);
  }
  return out;
}

/** The count for one game in one region (0 when absent). */
export function regionTally(f: Facets, game: string | null, r: Region): Tally {
  const g = game ? f.games.get(game) : null;
  if (game && !g) return zero();
  const c = r.kind === "continent" ? (g ? g.continents : f.continents).get(r.code) : (g ? g.countries : f.countries).get(r.code);
  return c ?? zero();
}

/** Continent tabs in display order, only continents with listings. */
export function continentTabs(f: Facets, game: string | null): { region: Region; t: Tally }[] {
  const g = game ? f.games.get(game) : null;
  const src = game ? g?.continents : f.continents;
  return CONTINENT_ORDER.filter((c) => (src?.get(c)?.n ?? 0) > 0).map((c) => ({ region: continentRegion(c), t: src!.get(c)! }))
    .sort((a, b) => b.t.n - a.t.n);
}

