// ── facets ────────────────────────────────────────────────────────────────
export type FacetRow = { game: string; cc: string | null; n: number; p: number; newest: Date | null };
export type Tally = { n: number; p: number; newest: number };
const zero = (): Tally => ({ n: 0, p: 0, newest: 0 });
const add = (t: Tally, r: { n: number; p: number; newest: Date | null }) => {
  t.n += r.n; t.p += r.p; t.newest = Math.max(t.newest, r.newest ? r.newest.getTime() : 0);
};

export type GameFacet = Tally & { game: string; countries: Map<string, Tally>; continents: Map<Continent, Tally>; unknown: Tally };
export type Facets = { total: Tally; games: Map<string, GameFacet>; countries: Map<string, Tally>; continents: Map<Continent, Tally> };

/** Roll the (game, country) GROUP BY rows up into every count the pages show. */
export function rollUp(rows: FacetRow[]): Facets {
  const out: Facets = { total: zero(), games: new Map(), countries: new Map(), continents: new Map() };
  for (const r of rows) {
    const cc = r.cc ? r.cc.toUpperCase() : null;
    const cont = continentOf(cc);
    let g = out.games.get(r.game);
    if (!g) { g = { game: r.game, ...zero(), countries: new Map(), continents: new Map(), unknown: zero() }; out.games.set(r.game, g); }
    add(g, r); add(out.total, r);
    if (cc && cont) {
      for (const [m, k] of [[g.countries, cc], [out.countries, cc]] as const) { const t = m.get(k) ?? zero(); add(t, r); m.set(k, t); }
      for (const m of [g.continents, out.continents]) { const t = m.get(cont) ?? zero(); add(t, r); m.set(cont, t); }
    } else add(g.unknown, r);
  }
  return out;
