    imageUrl: r.imageUrl, address: `${r.host}:${r.port}`, host: r.host, port: r.port,
    alsoKeys: r.ipKey ? [r.ipKey] : [],
    players: liveCountsFresh(r, now) ? r.players : null, maxPlayers: r.maxPlayers, country: r.country ? r.country.toUpperCase() : null, region: null, featured: false,
