import { rollUp, type FacetRow, type Facets } from "@/lib/directory-seo";
import { externalServerId, nxeonServerId } from "@/lib/directory-ids";

/**
 * Database side of the directory aggregate pages (home, games index, game, game + region, detail).
 * SQL pages and counts the third-party set (lib/directory-query-sql.ts); Nxeon-hosted entries (tens)
 * are loaded whole, merged as a pinned set and never paginated against. Every source degrades to
 * "none from there" on error, never a broken page (the `safe()` pattern of server-directory-data).
 *
 * Caching: the facet roll-up is one GROUP BY over the public set, kept in memory for FACET_TTL_MS per
 * process (the ingest refreshes rows a few times a day; counts a minute or two old are fine and are
 * labelled "at the last refresh"). List pages are one indexed query each and are not cached.
 */
const FACET_TTL_MS = 120_000;
const RULES_TTL_MS = 60_000;

const safe = async <T,>(p: Promise<T>, fallback: T): Promise<T> => { try { return await p; } catch { return fallback; } };

type Ctx = { externalOn: boolean; probeOn: boolean; nxeon: DirEntry[]; excludeKeys: string[] };
let ctxCache: { at: number; v: Ctx } | null = null;

/** Flags + Nxeon entries (deduped) + their connection keys, shared by every query on a page. */
export async function directoryContext(): Promise<Ctx> {
  if (ctxCache && Date.now() - ctxCache.at < 30_000) return ctxCache.v;
  const [externalOn, probeOn, raw] = await Promise.all([
    safe(getSettingBool("directory_external_show", false), false),
    safe(getSettingBool("directory_probe_enabled", false), false),
    safe(nxeonEntries(), [] as DirEntry[]),
  ]);
  const nxeon = rankEntries(dedupeEntries(raw).entries).map((e) => ({ ...e, publicId: e.source === "nxeon-paid" ? nxeonServerId(e.game, e.key) : null }));
  const keys = new Set<string>();
  for (const e of raw) for (const k of entryKeys(e)) keys.add(k);
  const v = { externalOn, probeOn, nxeon, excludeKeys: [...keys] };
  ctxCache = { at: Date.now(), v };
  return v;
}

const opts = (c: Ctx): PublicOpts => ({ probeOn: c.probeOn, now: Date.now(), excludeKeys: c.excludeKeys });

let facetCache: { at: number; v: Facets } | null = null;
/** Every count the aggregate pages show: third-party (SQL GROUP BY) plus Nxeon-hosted entries. */
export async function directoryFacets(): Promise<Facets> {
  if (facetCache && Date.now() - facetCache.at < FACET_TTL_MS) return facetCache.v;
  const c = await directoryContext();
  let rows: FacetRow[] = [];
  if (c.externalOn) {
    const q = buildFacets(opts(c));
    rows = await safe(db.$queryRawUnsafe<SqlFacetRow[]>(q.text, ...q.params), []);
  }
  for (const e of c.nxeon) rows.push({ game: e.game, cc: e.country, n: 1, p: e.players ?? 0, newest: null });
  const v = rollUp(rows);
  facetCache = { at: Date.now(), v };
  return v;
}

let rulesCache: { at: number; v: RuleSet } | null = null;
