  if (rulesCache && Date.now() - rulesCache.at < RULES_TTL_MS) return rulesCache.v;
  const v = await safe(loadRuleSet().then((r) => r.set), buildRuleSet().set);
  rulesCache = { at: Date.now(), v };
  return v;
}

