import "server-only";
import fs from "node:fs";
import path from "node:path";
import { headers } from "next/headers";
import { notFound, permanentRedirect } from "next/navigation";
import { db } from "@/lib/db";
import { APP_URL } from "@/components/marketing/StructuredData";
import { GAME_ART_SLUG, GAME_FAMILIES, GAME_GENRES, type GameFamily } from "@/lib/games";
import { countryFromHeaders } from "@/lib/geo-currency";
import { countryFromRequestIp } from "@/lib/geo-ip";
import { continentOf } from "@/lib/geo-continent";
import { pickFeatured, type DirEntry } from "@/lib/server-directory";
import { steamAttributionHtml, steamLogoPresent } from "@/lib/directory-steam";
import { providerAttributionHtml } from "@/lib/directory-ingest/providers/registry";
import { directoryContext, directoryFacets, findServer, listExternal, nxeonFor } from "@/lib/directory-query";
import { clampPage, normQ, PAGE_SIZE, type DirSort, type PlayersFilter } from "@/lib/directory-query-sql";
import { continentRegion, countryName, countryRegion, regionCountries, resolveRegionSlug, type Region } from "@/lib/directory-regions";
import { parseServerId } from "@/lib/directory-ids";
import {
  DIR, canonicalFor, continentTabs, gameDescription, gameIntro, gamePath, gamesPath, gameTitle, indexable, itemListLd,
  nearestAlternatives, regionDescription, regionFaq, regionIntro, regionPath, regionTally, regionTitle, serverPath,
  topCountries, trailFor, type Facets, type Tally,
} from "@/lib/directory-seo";
import { btn } from "./cards";
import { esc, nxmHref, type NxmLoad } from "./lib";
import { gameArt, gameName, gameRoute, isGameFamily, staged } from "./games-lib";
import { supportLine } from "./products-common";

/**
 * Server directory v2: the aggregate pages (Setting directory_v2_enabled; off = the v1 single page).
 *
 *   /game-servers/directory                  home: search, near you, Nxeon-hosted, games, regions, busiest, newest
 *   /game-servers/directory/games            every game Nxeon offers, with live counts (0-server games too)
 *   /game-servers/directory/<game>           one game: region tabs, filters, sort, numbered pages
 *   /game-servers/directory/<game>/<region>  one game in one continent or country
 *   /game-servers/directory/server/<id>      one server (noindex unless hosted on Nxeon)
 *
 * All markup is server-rendered HTML strings in the template's `page:html` slot (every value through
 * esc()); filters are plain GET forms so the pages work with JS off, page.js only adds conveniences.
 * Counts come from one cached GROUP BY (lib/directory-query.ts); lists are one SQL page each.
 */

export type HubView = "all" | "games" | "game" | "region" | "server";
const I = (n: string) => `<span data-au-icon="${n}" data-grad></span>`;
const fmt = (n: number) => n.toLocaleString("en-US");
const plural = (n: number, one: string, many = one + "s") => `${fmt(n)} ${n === 1 ? one : many}`;
const href = (route: string) => esc(nxmHref(route));
const CONTACT = "abuse@nxeon.cloud";

// ── static asset lookups (public/ is part of the build) ──────────────────
const seen = new Map<string, boolean>();
const has = (url: string) => {
  if (!seen.has(url)) { try { seen.set(url, fs.existsSync(path.join(process.cwd(), "public", url))); } catch { seen.set(url, false); } }
  return seen.get(url)!;
};
export const flagSrc = (cc: string | null | undefined) => (cc && has(`/flags/${cc.toLowerCase()}.png`) ? `/flags/${cc.toLowerCase()}.png` : null);
const logoSrc = (game: string) => { const a = GAME_ART_SLUG[game as GameFamily]; return a && has(`/games/art/${a.hero}_logo.png`) ? `/games/art/${a.hero}_logo.png` : null; };
const flagHtml = (cc: string | null | undefined) => {
  const f = flagSrc(cc);
  return f ? `<img class="dh-flag" src="${f}" alt="" width="20" height="14" loading="lazy" decoding="async">` : cc ? `<span class="dh-cc" aria-hidden="true">${esc(cc.toUpperCase())}</span>` : "";
};

// ── catalogue: which families checkout sells (active GamePlan) ───────────
let sellCache: { at: number; v: Set<string> } | null = null;
async function sellable(): Promise<Set<string>> {
  if (sellCache && Date.now() - sellCache.at < 300_000) return sellCache.v;
  let v = new Set<string>();
  try { v = new Set((await db.gamePlan.findMany({ where: { active: true }, select: { gameFamily: true }, distinct: ["gameFamily"] })).map((r) => r.gameFamily)); } catch { /* none */ }
  sellCache = { at: Date.now(), v };
  return v;
}

// ── visitor country (geo header, else offline geoip of the request IP; never stored) ──
async function visitorCountry(): Promise<string | null> {
  try {
    const h = await headers();
    const c = (countryFromHeaders(h) || countryFromRequestIp(h) || "").toUpperCase();
    return /^[A-Z]{2}$/.test(c) && c !== "XX" ? c : null;
  } catch { return null; }
}

// ── small pieces ─────────────────────────────────────────────────────────
const pad = (n: number) => String(n).padStart(2, "0");
const utcStamp = (ms: number) => { const d = new Date(ms); return `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())} ${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())} UTC`; };
function fresh(e: DirEntry): string {
  if (e.checkedAt) return `<time class="dr-chk" datetime="${new Date(e.checkedAt).toISOString()}" data-kind="Checked">Checked ${utcStamp(e.checkedAt)}</time>`;
  if (e.attribution && e.seenAt) return `<time class="dr-chk" datetime="${new Date(e.seenAt).toISOString()}" data-kind="Seen on the list">Seen on the list ${utcStamp(e.seenAt)}</time>`;
  return "";
}
/** Deterministic hue per server for the generated card art (no image files involved). */
const hueOf = (s: string) => { let h = 0; for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0; return h % 360; };
const initials = (name: string) => {
  const w = name.normalize("NFKC").replace(/[^\p{L}\p{N} ]+/gu, " ").trim().split(/\s+/).filter(Boolean);
  return (w.length ? (w.length > 1 ? w[0][0] + w[1][0] : w[0].slice(0, 2)) : "?").toUpperCase();
};
const detailHref = (e: DirEntry) => (e.publicId ? serverPath(e.publicId) : e.href);
const steamGame = (e: DirEntry) => e.attribution === "steam";

function playersHtml(e: DirEntry, compact = false): string {
  if (e.players != null) {
    const pct = e.maxPlayers ? Math.max(2, Math.min(100, Math.round((e.players / e.maxPlayers) * 100))) : 0;
    return `<div class="dh-pl${e.players > 0 ? " on" : ""}"><span><b>${fmt(e.players)}</b>${e.maxPlayers ? ` / ${fmt(e.maxPlayers)}` : ""} playing</span>${e.maxPlayers && !compact ? `<i aria-hidden="true" style="--f:${pct}%"></i>` : ""}</div>`;
  }
  return `<div class="dh-pl"><span>${e.maxPlayers ? `Up to ${fmt(e.maxPlayers)} players` : "Player count unknown"}</span></div>`;
}

function art(e: DirEntry, big = false): string {
  const cover = gameArt(e.game).cover ?? gameArt(e.game).hero;
  const img = e.imageUrl
    ? `<img src="${esc(e.imageUrl)}" alt="" loading="lazy" decoding="async" referrerpolicy="no-referrer">`
    : "";
  return `<div class="dh-art${big ? " big" : ""}${img ? " has-img" : ""}" aria-hidden="true" style="--h:${hueOf(e.key + e.name)}${cover ? `;--img:url('${esc(cover)}')` : ""}">${img}${img ? "" : `<b>${esc(initials(e.name))}</b>`}</div>`;
}

function badge(e: DirEntry): string {
  if (e.nxeon) return `<span class="dr-badge nx" title="Hosted on Nxeon">${I("shield")}Nxeon</span>`;
  return `<span class="dr-badge x" title="${e.attribution === "steam" ? "Found on the Steam server list" : "Found on a public server list"}">${e.attribution === "steam" ? "Steam list" : "Public list"}</span>`;
}

/** List card: the whole card is one link (stretched); Copy is its own button. */
export function hubCard(e: DirEntry): string {
  const to = detailHref(e);
  const where = e.country ? `${flagHtml(e.country)}<span>${esc(countryName(e.country))}</span>` : e.region ? `<span>${esc(e.region)}</span>` : "";
