// ── loaders ──────────────────────────────────────────────────────────────
export async function hubLoad(view: HubView, p: Record<string, string>): Promise<NxmLoad> {
  if (view === "all") return homeLoad(p);
  if (view === "games") return gamesLoad();
  if (view === "game" || view === "region") return listLoad(view, p);
  return serverLoad(p);
}

/** Resolve game + region params (404 unknown, 308 alias forms to the canonical slug). */
function resolveListParams(view: "game" | "region", p: Record<string, string>): { game: string; region: Region | null } {
  const game = String(p.game ?? "");
  if (!isGameFamily(game)) {
    const lower = game.toLowerCase();
    if (isGameFamily(lower)) permanentRedirect(nxmHref(view === "region" ? regionPath(lower, String(p.region ?? "")) : gamePath(lower)));
    notFound();
  }
  if (view === "game") return { game, region: null };
  const r = resolveRegionSlug(String(p.region ?? ""));
  if (!r) notFound();
  if ("redirect" in r) permanentRedirect(nxmHref(regionPath(game, r.redirect)));
  return { game, region: r.region };
}

async function homeLoad(p: Record<string, string>): Promise<NxmLoad> {
  const [c, f, sell, cc] = await Promise.all([directoryContext(), directoryFacets(), sellable(), visitorCountry()]);
  const filters = readFilters(p);
  const rr = p.region ? resolveRegionSlug(p.region) : null;
  const region = rr && "region" in rr ? rr.region : null;
  const browsing = !!filters.q || !!region;
  const gamesWith = [...f.games.values()].filter((g) => g.n > 0);
  const stats = statsHtml([
    ["server", fmt(f.total.n), "servers listed"],
    ["game", fmt(gamesWith.length), "games with servers"],
    ["globe", fmt(f.countries.size), "countries"],
    ["users", fmt(f.total.p), "playing at last refresh"],
  ]);
  const searchBox = `<form class="dh-hsearch" method="get" action="${href(DIR)}" role="search"><label class="dr-search">${SEARCH}<span class="visually-hidden">Search every server</span><input name="q" type="search" value="${esc(filters.q ?? "")}" placeholder="Server name, map or address" maxlength="60" autocomplete="off"></label><button type="submit" class="dh-go">Search</button></form>`;
  const heroHtml = hero({ trail: [{ name: "Server directory", path: "" }], chip: "Server directory", h1: "Find a server,", h1b: "join in one click.", sub: "Public game servers from around the world, the ones hosted on Nxeon and others found on public server lists. Pick a game or a region, copy the address and connect.", stats, extra: searchBox, big: true });

  const sections: string[] = [heroHtml];
  const shown: DirEntry[] = [];
  if (browsing) {
    const countries = region ? regionCountries(region) : null;
    const [ext, nx] = await Promise.all([listExternal({ q: filters.q, countries, players: filters.players, sort: filters.sort, page: filters.page }), nxeonFor(null, countries)]);
    const nxm = filters.q ? nx.filter((e) => (e.name + " " + e.address).toLowerCase().includes(filters.q!.toLowerCase())) : nx;
    const rows = filters.page === 1 ? [...nxm, ...ext.rows] : ext.rows;
    shown.push(...rows);
    const total = ext.total + nxm.length;
    const title = filters.q ? `Servers matching "${filters.q}"${region ? ` in ${region.label}` : ""}` : `Servers in ${region!.label}`;
    const extra: Record<string, string> = region ? { region: region.slug } : {};
    sections.push(`<section class="section dh-list" id="browse" aria-labelledby="br-title"><div class="container">`
      + sectionHead("br-title", title, "Every game. Open a game below to filter by country and more.")
      + regionChips(null, f, region, (r) => DIR + qs({ q: filters.q }, r ? { region: r.slug } : {}))
      + toolbar(DIR, filters, "Server name, map or address", extra)
      + `<p class="dh-count" aria-live="polite">${plural(total, "server")}${filters.page > 1 ? `, page ${filters.page}` : ""}</p>`
      + (ext.error ? `<p class="dh-warn" role="status">Couldn't load the full list right now; showing what we could.</p>` : "")
      + (rows.length ? `<ul class="dh-grid">${rows.map(hubCard).join("")}</ul>` : emptyBox("No servers match", "Try a shorter search, another region, or browse by game.", continentTabs(f, null).slice(0, 3).map((t) => ({ label: t.region.label, to: DIR + qs({}, { region: t.region.slug }), n: t.t.n })), hostCta(null, sell)))
      + pager(DIR, filters, total, extra) + attributionFor(rows, c.probeOn) + disclaimer() + `</div></section>`);
  } else {
    // near you: the visitor's country, else their continent
    const near: Region | null = cc ? (f.countries.get(cc)?.n ? countryRegion(cc) : continentOf(cc) && f.continents.get(continentOf(cc)!)?.n ? continentRegion(continentOf(cc)!) : null) : null;
    const [nearRows, busy, fresh8] = await Promise.all([
      near ? listExternal({ countries: regionCountries(near), players: "any", sort: "players", page: 1 }) : Promise.resolve(null),
      listExternal({ sort: "players", page: 1 }),
      listExternal({ sort: "newest", page: 1 }),
    ]);
    if (near && nearRows?.rows.length) {
      const r8 = nearRows.rows.slice(0, 8);
      shown.push(...r8);
      sections.push(`<section class="section dh-near" aria-labelledby="near-title"><div class="container">`
        + sectionHead("near-title", `Servers near you: ${near.label}`, "Based on the country your connection comes from. Closer servers usually mean lower ping.", moreLink(DIR + qs({}, { region: near.slug }), `All ${fmt(nearRows.total)} in ${near.label}`))
        + `<ul class="dh-row">${r8.map(miniCard).join("")}</ul></div></section>`);
    }
    const featured = pickFeatured(c.nxeon, 6).length ? pickFeatured(c.nxeon, 6) : c.nxeon.slice(0, 6);
    if (featured.length) {
      shown.push(...featured);
      sections.push(`<section class="section dh-feat" aria-labelledby="ft-title"><div class="container">`
        + sectionHead("ft-title", "Hosted on Nxeon", "Servers running on Nxeon whose owners chose to list them.")
        + `<ul class="dh-grid">${featured.map(hubCard).join("")}</ul></div></section>`);
    }
    const order = [...GAME_FAMILIES].map((g) => ({ g, t: f.games.get(g) })).filter((x) => (x.t?.n ?? 0) > 0)
      .sort((a, b) => (b.t!.p - a.t!.p) || (b.t!.n - a.t!.n));
    sections.push(`<section class="section dh-games-sec" id="games" aria-labelledby="gm-title"><div class="container">`
      + sectionHead("gm-title", "Browse by game", order.length ? "Sorted by players online. Every game Nxeon offers has a page, even before it has servers." : "Every game Nxeon offers has a page.", moreLink(gamesPath(), `All ${GAME_FAMILIES.length} games`))
      + `<ul class="dh-gtiles">${(order.length ? order.slice(0, 12).map((x) => gameTile(x.g, x.t, sell)) : [...sell].slice(0, 12).map((g) => gameTile(g, undefined, sell))).join("")}</ul></div></section>`);
    const tabs = continentTabs(f, null);
    if (tabs.length) {
      sections.push(`<section class="section dh-regions" id="regions" aria-labelledby="rg-title"><div class="container">`
        + sectionHead("rg-title", "Browse by region", "Where the listed servers are, by the country of their address.")
        + `<ul class="dh-conts">${tabs.map((t) => `<li><a href="${href(DIR + qs({}, { region: t.region.slug }))}"><b>${esc(t.region.label)}</b><span>${plural(t.t.n, "server")}</span>${t.t.p ? `<em>${fmt(t.t.p)} playing</em>` : ""}<i aria-hidden="true" style="--f:${Math.max(4, Math.round((t.t.n / Math.max(1, tabs[0].t.n)) * 100))}%"></i></a></li>`).join("")}</ul>`
        + countryChips(null, f, null, (r) => DIR + qs({}, { region: r.slug }), 16) + `</div></section>`);
    }
    if (busy.rows.length || fresh8.rows.length) {
      const b8 = busy.rows.slice(0, 8), n8 = fresh8.rows.slice(0, 8);
      shown.push(...b8, ...n8);
      sections.push(`<section class="section dh-two" aria-label="Busiest and newest"><div class="container dh-two-in">`
        + (b8.length ? `<div>${sectionHead("busy-title", "Most players now", "At the last refresh, across every game.")}<ul class="dh-stack">${b8.map(miniCard).join("")}</ul></div>` : "")
        + (n8.length ? `<div>${sectionHead("new-title", "Newly listed", "Servers that joined the directory most recently.")}<ul class="dh-stack">${n8.map(miniCard).join("")}</ul></div>` : "")
        + `</div></section>`);
    }
    sections.push(`<section class="section" aria-label="Sources"><div class="container">${attributionFor(shown, c.probeOn)}${disclaimer()}</div></section>`);
  }
  sections.push(howToList(), faqSection(faqCommon(c.probeOn)), finalBand("Host your own server", "Get a game server with a control panel, backups and mods, then list it here for others to find.", hostCta(null, sell)));
  return {
    slots: { "page:html": sections.join("") },
    jsonLd: [itemListLd({ appUrl: APP_URL, name: "Public game server directory", path: DIR, total: f.total.n, items: shown.map((e) => ({ name: e.name, path: detailHref(e) })) })],
    crumb: "Server directory",
  };
}

function howToList(): string {
  const rows = [
    ["Run your server on Nxeon", "Order a game server, or create a free Minecraft one. Listing yourself is for servers hosted here."],
    ["Switch on the Public Directory", "Open your server's Settings tab, turn the Public Directory card on and add a short description."],
    ["Players find you here", "A listed server appears with the Nxeon badge while it is running. Switch it off any time and it leaves straight away."],
  ];
  return `<section class="section" id="list" aria-labelledby="ls-title"><div class="container">${sectionHead("ls-title", "List your own server here", "Owners choose to be listed, and can switch it off at any time.")}`
    + `<ol class="dr-steps">${rows.map(([h, t], i) => `<li class="au-card"><span class="n">0${i + 1}</span><h3>${esc(h)}</h3><p>${esc(t)}</p></li>`).join("")}</ol></div></section>`;
}

async function gamesLoad(): Promise<NxmLoad> {
  const [c, f, sell] = await Promise.all([directoryContext(), directoryFacets(), sellable()]);
  const withServers = [...GAME_FAMILIES].filter((g) => (f.games.get(g)?.n ?? 0) > 0).sort((a, b) => (f.games.get(b)!.p - f.games.get(a)!.p) || (f.games.get(b)!.n - f.games.get(a)!.n));
  const without = [...GAME_FAMILIES].filter((g) => !(f.games.get(g)?.n)).sort((a, b) => Number(sell.has(b)) - Number(sell.has(a)) || gameName(a).localeCompare(gameName(b)));
  const stats = statsHtml([["game", String(GAME_FAMILIES.length), "games"], ["server", fmt(withServers.length), "with servers listed"], ["users", fmt(f.total.p), "playing at last refresh"]]);
  const html = hero({ trail: trailFor("games"), chip: "Server directory", h1: "Every game,", h1b: "every server list.", sub: "Pick a game to see its public servers by region. Games without a public server list show the servers their owners list on Nxeon.", stats })
    + `<section class="section" aria-labelledby="gw-title"><div class="container">${sectionHead("gw-title", "Games with servers listed", "Sorted by players online at the last refresh.")}<ul class="dh-gtiles">${withServers.map((g) => gameTile(g, f.games.get(g), sell)).join("")}</ul></div></section>`
    + `<section class="section" aria-labelledby="go-title" style="padding-top:0"><div class="container">${sectionHead("go-title", "More games", "No public servers listed yet. Be the first: host one on Nxeon and list it.")}<ul class="dh-gtiles">${without.map((g) => gameTile(g, undefined, sell)).join("")}</ul></div></section>`
    + faqSection(faqCommon(c.probeOn))
    + finalBand("Host your own server", "Every game on this page that Nxeon sells can be live in minutes, then listed here.", hostCta(null, sell));
  return {
    slots: { "page:html": html },
    jsonLd: [itemListLd({ appUrl: APP_URL, name: "Game server directory: all games", path: gamesPath(), total: GAME_FAMILIES.length, items: [...withServers, ...without].map((g) => ({ name: `${gameName(g)} servers`, path: gamePath(g) })) })],
    trail: trailFor("games").map((t) => ({ name: t.name, path: t.path })),
  };
}

async function listLoad(view: "game" | "region", p: Record<string, string>): Promise<NxmLoad> {
  const { game, region } = resolveListParams(view, p);
  const [c, f, sell] = await Promise.all([directoryContext(), directoryFacets(), sellable()]);
  const filters = readFilters(p);
  const name = gameName(game);
  const countries = region ? regionCountries(region) : null;
  const [ext, nxAll] = await Promise.all([
    listExternal({ game, countries, q: filters.q, players: filters.players, sort: filters.sort, page: filters.page }),
    nxeonFor(game, countries),
  ]);
  const nx = filters.q ? nxAll.filter((e) => (e.name + " " + e.address).toLowerCase().includes(filters.q!.toLowerCase())) : nxAll;
  if (filters.page > 1 && !ext.rows.length) notFound();
  const g = f.games.get(game);
  const t: Tally = region ? regionTally(f, game, region) : (g ?? { n: 0, p: 0, newest: 0 });
  const base = region ? regionPath(game, region.slug) : gamePath(game);
  const trail = trailFor(view, { game, gameName: name, region: region ?? undefined });
  const ncountries = region?.kind === "country" ? 1 : region ? topCountries(f, game, 999, region.code).length : g?.countries.size ?? 0;
  const stats = statsHtml([
    ["server", fmt(t.n), t.n === 1 ? "server listed" : "servers listed"],
    ["users", fmt(t.p), "playing at last refresh"],
    ...(region?.kind === "country" ? [] : [["globe", fmt(ncountries), ncountries === 1 ? "country" : "countries"] as [string, string, string]]),
    ...(nxAll.length ? [["shield", fmt(nxAll.length), "on Nxeon"] as [string, string, string]] : []),
  ]);
  const notHosted = !sell.has(game);
  const h = hero({
    game, trail, chip: notHosted ? `${name} directory · not hosted by Nxeon` : `${name} directory`,
    h1: region ? `${name} servers in ${region.label}` : `${name} servers`,
    sub: region ? regionIntro(name, region, t, f, game) : gameIntro(name, f, game), stats,
  });
  const baseFor = (r: Region | null) => (r ? regionPath(game, r.slug) : gamePath(game)) + qs({ q: filters.q, players: filters.players, sort: filters.sort });
  const rows = filters.page === 1 ? [...nx, ...ext.rows] : ext.rows;
  const total = ext.total + nx.length;
  const alts = region ? nearestAlternatives(f, game, region).map((x) => ({ label: x.region.label, to: regionPath(game, x.region.slug), n: x.t.n })) : [];
  const emptyText = t.n
    ? "Nothing matches these filters. Clear them, or try a neighbouring region."
    : region
      ? `No public ${name} servers are listed in ${region.label} right now.`
      : `No public ${name} servers are listed yet. Some games have no public server list we can use; servers appear here when their owner hosts one on Nxeon and lists it.`;
  const others = [...GAME_FAMILIES].filter((x) => x !== game && (f.games.get(x)?.n ?? 0) > 0 && (GAME_GENRES[x] ?? []).some((gg) => (GAME_GENRES[game as GameFamily] ?? []).includes(gg)))
    .sort((a, b) => f.games.get(b)!.n - f.games.get(a)!.n).slice(0, 6);
  const top5 = region ? rows.filter((e) => !e.nxeon).slice(0, 5) : [];
  const faq: [string, string][] = region
    ? regionFaq(name, region, t, top5.map((e) => ({ name: e.name, players: e.players, max: e.maxPlayers })))
    : [[`How many ${name} servers are listed?`, t.n ? `${plural(t.n, `public ${name} server`)} right now, in ${plural(ncountries, "country", "countries")}. The list refreshes several times a day.` : `None yet. Servers appear here when their owner lists one hosted on Nxeon, or when a public server list has them.`], ...faqCommon(c.probeOn).slice(0, 4)];
  const html = h
    + `<section class="section dh-list" id="browse" aria-labelledby="br-title"><div class="container">`
    + regionChips(game, f, region, baseFor)
    + countryChips(game, f, region, (r) => baseFor(r))
    + toolbar(base, filters, `Search ${name} servers by name, map or address`)
    + `<p class="dh-count" id="br-title" aria-live="polite">${plural(total, "server")}${filters.page > 1 ? `, page ${filters.page} of ${Math.ceil(ext.total / PAGE_SIZE)}` : ""}${isFiltered(filters) ? " match these filters" : ""}</p>`
    + (ext.error ? `<p class="dh-warn" role="status">Couldn't load the full list right now; showing what we could.</p>` : "")
    + (rows.length ? `<ul class="dh-grid">${rows.map(hubCard).join("")}</ul>` : emptyBox(t.n ? "No servers match" : region ? `No ${name} servers in ${region.label}` : `No ${name} servers listed yet`, emptyText, alts, hostCta(game, sell)))
    + pager(base, filters, ext.total)
    + attributionFor(rows, c.probeOn) + disclaimer() + `</div></section>`
    + (top5.length >= 3 ? `<section class="section dh-seo" aria-labelledby="top-title"><div class="container">${sectionHead("top-title", `Busiest ${name} servers in ${region!.label}`, "At the last refresh.")}`
      + `<div class="dh-table-wrap"><table class="dh-table"><thead><tr><th scope="col">Server</th><th scope="col">Players</th><th scope="col">Map</th><th scope="col">Address</th></tr></thead><tbody>`
      + top5.map((e) => `<tr><th scope="row">${e.publicId ? `<a href="${href(serverPath(e.publicId))}">${esc(e.name)}</a>` : esc(e.name)}</th><td>${e.players != null ? `${fmt(e.players)}${e.maxPlayers ? ` / ${fmt(e.maxPlayers)}` : ""}` : "–"}</td><td>${esc(e.map ?? "–")}</td><td><code>${esc(e.address)}</code></td></tr>`).join("")
      + `</tbody></table></div></div></section>` : "")
    + (others.length ? `<section class="section dh-others" aria-labelledby="ot-title"><div class="container">${sectionHead("ot-title", `Players of ${name} also browse`, "Games in the same genre with servers listed.")}<ul class="dh-gtiles small">${others.map((x) => gameTile(x, f.games.get(x), sell)).join("")}</ul></div></section>` : "")
    + faqSection(faq, region ? `${name} servers in ${region.label}` : `${name} server questions`)
    + finalBand(notHosted ? "Host your own game server" : `Host your own ${name} server`, notHosted ? `${name} isn't one of the games Nxeon hosts yet. See the games you can run on Nxeon today.` : `A ${name} server with a control panel, backups and mods, live in minutes. List it here for players to find.`, hostCta(game, sell));
  return {
    slots: { "page:html": html },
    jsonLd: rows.length ? [itemListLd({ appUrl: APP_URL, name: region ? `${name} servers in ${region.label}` : `${name} servers`, path: base, total, items: rows.map((e) => ({ name: e.name, path: detailHref(e) })) })] : [],
    trail: trail.map((x) => ({ name: x.name, path: x.path })),
  };
}

async function serverLoad(p: Record<string, string>): Promise<NxmLoad> {
  const id = parseServerId(String(p.id ?? ""));
  if (!id) notFound();
  if (p.id !== `${id.game}-${id.hash}`) permanentRedirect(nxmHref(serverPath(`${id.game}-${id.hash}`)));
  const [c, sell] = await Promise.all([directoryContext(), sellable()]);
  const e = await findServer(id.game, id.hash);
  if (!e) notFound();
  const name = gameName(e.game);
  const near = e.country ? countryRegion(e.country) : null;
  const sim = (await listExternal({ game: e.game, countries: near ? regionCountries(near.kind === "country" ? near : near) : null, page: 1 })).rows.filter((x) => x.publicId !== e.publicId).slice(0, 4);
  const trail = trailFor("server", { game: e.game, gameName: name, serverName: e.name });
  const about = e.description || e.tagline || factualLine(e);
  const facts: string[] = [
    e.country ? `<li>${flagHtml(e.country)}${esc(countryName(e.country))}</li>` : e.region ? `<li>${esc(e.region)}</li>` : "",
    `<li>${esc(name)}</li>`,
    e.map ? `<li>Map ${esc(e.map)}</li>` : "",
    e.maxPlayers ? `<li>${fmt(e.maxPlayers)} slots</li>` : "",
  ].filter(Boolean);
  const steamLink = steamGame(e) && /^\d{1,3}(\.\d{1,3}){3}:\d+$/.test(e.address) ? `<a class="nxm-glassbtn" href="steam://connect/${esc(e.address)}" rel="nofollow"><span class="nxm-bt">Connect with Steam</span></a>` : "";
  const html = `<section class="dh-hero dh-detail" id="top" aria-labelledby="dh-title"><div class="dh-hero-art" aria-hidden="true" style="background-image:url('${esc(gameArt(e.game).hero ?? "")}')"></div><div class="dr-shade" aria-hidden="true"></div>`
    + `<div class="container dh-hero-in">${crumbsHtml(trail)}<div class="dh-d-grid">${art(e, true)}<div><div class="dh-h">${badge(e)}</div><h1 id="dh-title">${esc(e.name)}</h1><ul class="dh-facts">${facts.join("")}</ul>`
    + `<div class="dh-connect"><code>${esc(e.address)}</code><button type="button" class="dr-copy" data-copy="${esc(e.address)}" aria-label="Copy the server address">Copy address</button>${steamLink}</div>`
    + playersHtml(e) + `<p class="dh-fresh">${fresh(e)}</p></div></div></div></section>`
    + `<section class="section dh-about" aria-labelledby="ab-title"><div class="container dh-about-in"><div class="au-card"><h2 class="h2" id="ab-title">About this server</h2><p>${esc(about)}</p>`
    + (e.nxeon ? `<p class="dh-note">This server is hosted on Nxeon and listed by its owner.</p>` : `<p class="dh-note">Nxeon does not run this server. ${e.attribution === "steam" ? "It was found on the Steam server list" : "It was found on a public server list"}; details may be out of date. To have it removed, email <a href="mailto:${CONTACT}">${CONTACT}</a>.</p>`)
    + `</div><div class="au-card dh-side"><h2 class="h3">More ${esc(name)} servers</h2><p><a href="${href(gamePath(e.game))}">All ${esc(name)} servers</a></p>${near ? `<p><a href="${href(regionPath(e.game, near.slug))}">${esc(name)} servers in ${esc(near.label)}</a></p>` : ""}<div class="dh-side-cta">${hostCta(e.game, sell)}</div></div></div></section>`
    + (sim.length ? `<section class="section" aria-labelledby="sm-title" style="padding-top:0"><div class="container">${sectionHead("sm-title", near ? `Similar servers in ${near.label}` : `More ${name} servers`, "")}<ul class="dh-grid">${sim.map(hubCard).join("")}</ul></div></section>` : "")
    + `<section class="section" aria-label="Sources" style="padding-top:0"><div class="container">${attributionFor([e, ...sim], c.probeOn)}</div></section>`;
  return { slots: { "page:html": html }, jsonLd: [], trail: trail.filter((t) => t.path).map((t) => ({ name: t.name, path: t.path })), crumb: e.name };
}

/** The factual fallback "about" line: only stored fields, no adjectives or claims (spec section 4). */
export function factualLine(e: Pick<DirEntry, "game" | "country" | "map" | "maxPlayers">): string {
  return `${gameName(e.game)} server${e.country ? ` in ${countryName(e.country)}` : ""}. ${e.map ? `Map: ${e.map}. ` : ""}${e.maxPlayers ? `${fmt(e.maxPlayers)} slots.` : ""}`.trim();
}

// ── metadata ─────────────────────────────────────────────────────────────
export async function hubMeta(view: HubView, p: Record<string, string>) {
  const f = await directoryFacets();
  if (view === "all") {
    const filters = readFilters(p);
    const filtered = !!filters.q || !!p.region || isFiltered(filters) || filters.page > 1;
    return {
      title: "Game Server List: Public Servers for Every Game",
      description: `${plural(f.total.n, "public game server")} across ${plural([...f.games.values()].filter((g) => g.n).length, "game")} and ${plural(f.countries.size, "country", "countries")}. Browse by game or region, copy an address and connect.`,
      image: gameArt("minecraft").hero ?? undefined, canonical: DIR,
      noindex: !indexable({ kind: "home", listings: f.total.n, filtered }),
    };
  }
  if (view === "games") {
    return { title: "All Games: Public Server Lists by Game", description: `Server lists for all ${GAME_FAMILIES.length} games Nxeon offers, with live counts. Pick a game to see its public servers by region.`, image: gameArt("minecraft").hero ?? undefined, canonical: gamesPath() };
  }
  if (view === "server") {
    const id = parseServerId(String(p.id ?? ""));
    if (!id) notFound();
    const e = await findServer(id.game, id.hash);
    if (!e) notFound();
    return {
      title: `${e.name.slice(0, 60)}: ${gameName(e.game)} Server`,
      description: `${factualLine(e)} Copy the address and connect.`.slice(0, 300),
      image: gameArt(e.game).hero ?? undefined, canonical: serverPath(`${id.game}-${id.hash}`),
      noindex: !indexable({ kind: "server", listings: 1, nxeonHosted: e.nxeon }),
    };
  }
  const { game, region } = resolveListParams(view, p);
  const filters = readFilters(p);
  const name = gameName(game);
  const g = f.games.get(game);
  const t = region ? regionTally(f, game, region) : (g ?? { n: 0, p: 0, newest: 0 });
  const base = region ? regionPath(game, region.slug) : gamePath(game);
  const filtered = isFiltered(filters);
  return {
    title: region ? regionTitle(name, region) : gameTitle(name),
    description: region ? regionDescription(name, region, t) : gameDescription(name, t, g?.countries.size ?? 0),
    image: gameArt(game).hero ?? undefined,
    canonical: canonicalFor(base, { page: filters.page, filtered }),
    noindex: !indexable({ kind: region ? "region" : "game", listings: t.n, page: filters.page, filtered }),
  };
}

