    + art(e)
    + `<div class="dh-body"><div class="dh-h"><h3 title="${esc(e.name)}">${to ? `<a class="dh-link" href="${href(to)}">${esc(e.name)}</a>` : esc(e.name)}</h3>${badge(e)}</div>`
    + `<p class="dh-sub"><span class="dh-game">${esc(gameName(e.game))}</span>${where ? `<span class="dh-where">${where}</span>` : ""}</p>`
    + playersHtml(e)
    + (chips ? `<ul class="dh-chips" aria-label="Details">${chips}</ul>` : "")
