const SEARCH = `<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></svg>`;

// ── filters (URL state) ──────────────────────────────────────────────────
export type HubFilters = { q: string | null; players: PlayersFilter; sort: DirSort; page: number };
export function readFilters(p: Record<string, string>): HubFilters {
  const players = p.players === "has" || p.players === "notfull" ? p.players : "any";
  const sort = p.sort === "newest" || p.sort === "name" ? p.sort : "players";
  return { q: normQ(p.q), players, sort, page: clampPage(p.page) };
}
const isFiltered = (f: HubFilters) => !!f.q || f.players !== "any" || f.sort !== "players";
/** Query string for a list URL, keeping only non-default keys (stable order). */
export function qs(f: Partial<HubFilters>, extra: Record<string, string | null | undefined> = {}): string {
  const u = new URLSearchParams();
  for (const [k, v] of Object.entries(extra)) if (v) u.set(k, v);
  if (f.q) u.set("q", f.q);
  if (f.players && f.players !== "any") u.set("players", f.players);
  if (f.sort && f.sort !== "players") u.set("sort", f.sort);
  if (f.page && f.page > 1) u.set("page", String(f.page));
  const s = u.toString();
  return s ? `?${s}` : "";
}

function toolbar(action: string, f: HubFilters, placeholder: string, hidden: Record<string, string> = {}): string {
  const opt = (v: string, l: string, cur: string) => `<option value="${v}"${v === cur ? " selected" : ""}>${esc(l)}</option>`;
  return `<form class="dh-tools" method="get" action="${href(action)}" role="search">`
    + Object.entries(hidden).map(([k, v]) => `<input type="hidden" name="${esc(k)}" value="${esc(v)}">`).join("")
    + `<label class="dr-search">${SEARCH}<span class="visually-hidden">Search servers</span><input name="q" type="search" value="${esc(f.q ?? "")}" placeholder="${esc(placeholder)}" maxlength="60" autocomplete="off"></label>`
    + `<details class="dh-more"${f.players !== "any" || f.sort !== "players" ? " open" : ""}><summary>Filters &amp; sort</summary><div class="dh-more-in">`
    + `<label><span>Players</span><select name="players">${opt("any", "Any", f.players)}${opt("has", "Has players", f.players)}${opt("notfull", "Not full", f.players)}</select></label>`
    + `<label><span>Sort</span><select name="sort">${opt("players", "Most players", f.sort)}${opt("newest", "Newest", f.sort)}${opt("name", "Name A to Z", f.sort)}</select></label>`
    + `</div></details>`
    + `<button type="submit" class="dh-go">Search</button>`
    + (isFiltered(f) ? `<a class="dh-reset" href="${href(action)}${Object.keys(hidden).length ? esc(qs({}, hidden)) : ""}">Clear</a>` : "")
    + `</form>`;
}

function pager(base: string, f: HubFilters, total: number, extra: Record<string, string> = {}): string {
  const pages = Math.min(Math.ceil(total / PAGE_SIZE), 200);
  if (pages <= 1) return "";
  const cur = f.page;
  const nums = new Set<number>([1, pages, cur - 1, cur, cur + 1, cur - 2, cur + 2].filter((n) => n >= 1 && n <= pages));
  const sorted = [...nums].sort((a, b) => a - b);
  const link = (n: number, label: string, rel?: string) => `<a href="${href(base)}${esc(qs({ ...f, page: n }, extra))}"${rel ? ` rel="${rel}"` : ""}${n === cur ? ` aria-current="page"` : ""}>${label}</a>`;
  let out = cur > 1 ? link(cur - 1, "Previous", "prev") : "";
  let last = 0;
  for (const n of sorted) { if (n - last > 1) out += `<span aria-hidden="true">…</span>`; out += link(n, String(n)); last = n; }
  if (cur < pages) out += link(cur + 1, "Next", "next");
  return `<nav class="dh-pager" aria-label="Pages">${out}</nav>`;
}

function regionChips(game: string | null, f: Facets, active: Region | null, baseFor: (r: Region | null) => string): string {
  const tabs = continentTabs(f, game);
  if (!tabs.length) return "";
  const all = game ? (f.games.get(game)?.n ?? 0) : f.total.n;
  const a = (r: Region | null, label: string, n: number) => {
    const on = (r?.slug ?? null) === (active?.slug ?? null) || (!!r && active?.kind === "country" && r.kind === "continent" && active.continent === r.code);
    return `<a class="dh-tab${on ? " on" : ""}" href="${href(baseFor(r))}"${on ? ` aria-current="${r?.slug === active?.slug ? "page" : "true"}"` : ""}>${esc(label)}<b>${fmt(n)}</b></a>`;
  };
  return `<nav class="dh-tabs" aria-label="Regions">${a(null, "All regions", all)}${tabs.map((t) => a(t.region, t.region.label, t.t.n)).join("")}</nav>`;
}

function countryChips(game: string | null, f: Facets, active: Region | null, baseFor: (r: Region) => string, limit = 14): string {
  const within = active?.kind === "continent" ? active.code : active?.kind === "country" ? active.continent : undefined;
  const list = topCountries(f, game, limit, within);
  if (!list.length) return "";
  return `<ul class="dh-ccs" aria-label="Countries">${list.map((x) => {
    const on = active?.slug === x.region.slug;
    return `<li><a href="${href(baseFor(x.region))}"${on ? ` aria-current="page" class="on"` : ""}>${flagHtml(x.region.code)}${esc(x.region.label)}<b>${fmt(x.t.n)}</b></a></li>`;
  }).join("")}</ul>`;
}

