/* ============ Directory v2: filters submit on change, copy is announced, Esc closes the filter panel ============ */
(function hub() {
  const form = $('.dh-tools'); if (!form) return;
  $$('select', form).forEach(s => s.addEventListener('change', () => { const pg = form.querySelector('input[name="page"]'); if (pg) pg.remove(); form.requestSubmit ? form.requestSubmit() : form.submit(); }));
  form.addEventListener('submit', () => { $$('input,select', form).forEach(el => { if (!el.value || (el.name === 'players' && el.value === 'any') || (el.name === 'sort' && el.value === 'players')) el.disabled = true; }); });
  document.addEventListener('keydown', e => { if (e.key === 'Escape') $$('details.dh-more[open]').forEach(d => { d.open = false; d.querySelector('summary').focus(); }); });
})();
(function announce() {
  if (!$('.dh-join, .dh-connect')) return;
  const live = document.createElement('p'); live.className = 'visually-hidden'; live.setAttribute('aria-live', 'polite'); document.body.appendChild(live);
  $$('.dr-copy').forEach(b => b.addEventListener('click', () => { setTimeout(() => { if (b.classList.contains('ok')) live.textContent = 'Address copied'; }, 50); }));
})();
EOF
