import "server-only";
import { getSettingBool } from "@/lib/settings";
import { GAME_FAMILIES } from "@/lib/games";
import { CONTINENT_ORDER } from "@/lib/geo-continent";
import { continentRegion, countryRegion } from "@/lib/directory-regions";
import { directoryContext, directoryFacets } from "@/lib/directory-query";
import { DIR, gamePath, gamesPath, indexable, regionPath, serverPath, type Facets } from "@/lib/directory-seo";

/**
 * The "directory" child sitemap (/sitemap/directory.xml) for the directory v2 aggregate pages.
 * ONLY indexable pages (lib/directory-seo.ts `indexable`): home, all-games, game pages with
 * >= GAME_INDEX_MIN listings, game + continent/country pages with >= REGION_INDEX_MIN listings, and
 * detail pages of Nxeon-hosted servers. Never a third-party server page, a filter or page 2+.
 * <lastmod> = the newest listing's first-seen time for that page (a real content-change date); absent
 * when unknown (Nxeon-hosted only). Empty when directory_v2_enabled is off (v1 keeps its old entries).
 */
export type DirSitemapEntry = { url: string; lastModified?: Date };

export async function directoryV2Enabled(): Promise<boolean> {
  try { return await getSettingBool("directory_v2_enabled", false); } catch { return false; }
}

/** Pure part: which aggregate paths to list from a facet roll-up. Exported for tests. */
export function directorySitemapPaths(f: Facets, nxeonIds: string[] = []): { path: string; newest: number }[] {
  const out: { path: string; newest: number }[] = [{ path: DIR, newest: f.total.newest }, { path: gamesPath(), newest: f.total.newest }];
  for (const game of GAME_FAMILIES) {
    const g = f.games.get(game);
    if (!g || !indexable({ kind: "game", listings: g.n })) continue;
    out.push({ path: gamePath(game), newest: g.newest });
    for (const c of CONTINENT_ORDER) {
      const t = g.continents.get(c);
      if (t && indexable({ kind: "region", listings: t.n })) out.push({ path: regionPath(game, continentRegion(c).slug), newest: t.newest });
    }
    for (const [cc, t] of g.countries) {
      const r = countryRegion(cc);
      if (r && indexable({ kind: "region", listings: t.n })) out.push({ path: regionPath(game, r.slug), newest: t.newest });
    }
  }
  for (const id of nxeonIds) out.push({ path: serverPath(id), newest: 0 });
  return out;
}

export async function directorySitemapEntries(appUrl: string): Promise<DirSitemapEntry[]> {
  if (!(await directoryV2Enabled())) return [];
  try {
    const [f, c] = await Promise.all([directoryFacets(), directoryContext()]);
    const ids = c.nxeon.map((e) => e.publicId).filter((x): x is string => !!x);
    return directorySitemapPaths(f, ids).map((e) => ({ url: appUrl + e.path, ...(e.newest ? { lastModified: new Date(e.newest) } : {}) }));
  } catch {
    return [];
  }
}

