/**
 * Directory v2 aggregate pages: pure rules (region slugs, SQL builder, index/canonical rules,
 * copy, structured data, sitemap paths, public ids). No database, no network.
 */
import test from "node:test";
import assert from "node:assert/strict";
import { CONTINENT_ORDER, countriesOf } from "../lib/geo-continent";
import { CONTINENT_SLUG, allCountryCodes, countryName, countrySlug, regionCountries, resolveRegionSlug } from "../lib/directory-regions";
import { MAX_PAGE, PAGE_SIZE, buildByShortId, buildFacets, buildPage, buildWhere, clampPage, likeEscape, normQ, orderBy } from "../lib/directory-query-sql";
import {
  DIR, GAME_INDEX_MIN, REGION_INDEX_MIN, canonicalFor, continentTabs, directorySitemapPaths, gameDescription, gameIntro, indexable,
  itemListLd, nearestAlternatives, regionDescription, regionFaq, regionIntro, regionTally, rollUp, topCountries, trailFor, type FacetRow,
} from "../lib/directory-seo";
import { externalServerId, nxeonServerId, parseServerId, shortHash } from "../lib/directory-ids";
import { GAME_FAMILIES } from "../lib/games";
import { steamAttributionHtml } from "../lib/directory-steam";

const NOW = Date.parse("2026-10-05T10:00:00Z");
const O = { probeOn: false, now: NOW };

// ── region slugs ─────────────────────────────────────────────────────────
test("every continent-mapped country has one unique slug that never collides with a continent", () => {
  const seen = new Map<string, string>();
  const conts = new Set(Object.values(CONTINENT_SLUG));
  for (const cc of allCountryCodes()) {
    const s = countrySlug(cc)!;
    assert.match(s, /^[a-z0-9]+(-[a-z0-9]+)*$/, `${cc} -> ${s}`);
    assert.ok(!seen.has(s), `${cc} and ${seen.get(s)} share ${s}`);
    assert.ok(!conts.has(s), `${cc} collides with a continent slug`);
    seen.set(s, cc);
    const r = resolveRegionSlug(s);
    assert.ok(r && "region" in r && r.region.kind === "country" && r.region.code === cc, `${s} resolves back to ${cc}`);
  }
  assert.equal(seen.size, CONTINENT_ORDER.reduce((n, c) => n + countriesOf(c).length, 0));
});

test("region slugs: canonical, aliases redirect, unknown is null", () => {
  assert.deepEqual(resolveRegionSlug("europe"), { region: { kind: "continent", code: "EU", slug: "europe", label: "Europe" } });
  const sg = resolveRegionSlug("singapore");
  assert.ok(sg && "region" in sg && sg.region.kind === "country" && sg.region.continent === "AS");
  assert.deepEqual(resolveRegionSlug("de"), { redirect: "germany" });
  assert.deepEqual(resolveRegionSlug("DE"), { redirect: "germany" });
  assert.deepEqual(resolveRegionSlug("Germany"), { redirect: "germany" });
  assert.deepEqual(resolveRegionSlug("Europe"), { redirect: "europe" });
  assert.deepEqual(resolveRegionSlug("uk"), { redirect: "united-kingdom" });
  assert.deepEqual(resolveRegionSlug("usa"), { redirect: "united-states" });
  assert.deepEqual(resolveRegionSlug("us"), { redirect: "united-states" });
  for (const bad of ["narnia", "", "x", "../etc", "a".repeat(80), "zz"]) assert.equal(resolveRegionSlug(bad), null, bad);
  assert.equal(countrySlug("HK"), "hong-kong");
  assert.equal(countrySlug("KR"), "south-korea");
  assert.equal(countryName("gb"), "United Kingdom");
  assert.deepEqual(regionCountries({ kind: "country", code: "SG", slug: "singapore", label: "Singapore", continent: "AS" }), ["SG"]);
});

// ── SQL builder ──────────────────────────────────────────────────────────
const placeholders = (t: string) => [...new Set([...t.matchAll(/\$(\d+)/g)].map((m) => Number(m[1])))].sort((a, b) => a - b);

test("buildWhere: public set, values only as parameters, placeholders contiguous", () => {
  const w = buildWhere({ game: "rust", countries: ["de", "FR"], q: "Moose_100%", players: "has" }, { ...O, excludeKeys: ["1.2.3.4:28015"] });
  assert.match(w.text, /"hidden" = false/);
  assert.match(w.text, /"blockedReason" IS NULL/);
  assert.match(w.text, /"probeStatus" <> 'DEAD'/);
  assert.ok(!w.text.includes("rust") && !w.text.includes("Moose") && !w.text.includes("1.2.3.4"), "no value spliced into SQL text");
  assert.deepEqual(placeholders(w.text), w.params.map((_, i) => i + 1));
  assert.ok(w.params.includes("rust"));
  assert.ok(w.params.some((p) => Array.isArray(p) && (p as string[]).join() === "DE,FR"));
  assert.ok(w.params.includes("%moose\\_100\\%%"), "LIKE wildcards escaped, lower-cased");
  assert.match(w.text, /"players" > 0/);
});

test("buildWhere: prober on requires a recent ALIVE answer; no game = every game", () => {
  const w = buildWhere({}, { probeOn: true, now: NOW });
  assert.match(w.text, /"probeStatus" = 'ALIVE' AND "lastAliveAt" >=/);
  assert.ok(!/"game" =/.test(w.text));
  assert.equal(normQ(" a "), null);
  assert.equal(normQ("x".repeat(200))!.length, 60);
  assert.equal(likeEscape("a\\b%c_d"), "a\\\\b\\%c\\_d");
});

test("buildPage: LIMIT/OFFSET are the last two parameters, page clamped", () => {
  const b = buildPage({ game: "cs2", page: 3, sort: "newest" }, O);
  assert.deepEqual(b.params.slice(-2), [PAGE_SIZE, 2 * PAGE_SIZE]);
  assert.match(b.text, new RegExp(`LIMIT \\$${b.params.length - 1} OFFSET \\$${b.params.length}$`));
  assert.match(b.text, /ORDER BY "firstSeenAt" DESC/);
  assert.match(b.text, /count\(\*\) OVER\(\)/);
  assert.equal(clampPage("0"), 1); assert.equal(clampPage("abc"), 1); assert.equal(clampPage("99999"), MAX_PAGE); assert.equal(clampPage("2.7"), 2);
  assert.equal(orderBy(undefined), orderBy("players"));
  assert.match(orderBy("name"), /lower\("name"\) ASC/);
});

test("buildFacets / buildByShortId are parameterised", () => {
  const f = buildFacets(O, "rust");
  assert.match(f.text, /GROUP BY 1,2$/);
  assert.deepEqual(placeholders(f.text), f.params.map((_, i) => i + 1));
  const s = buildByShortId("rust", "0123456789", O);
  assert.equal(s.params.at(-1), "0123456789");
  assert.match(s.text, /sha256\(convert_to\("connKey", 'UTF8'\)\)/);
});

// ── public ids ───────────────────────────────────────────────────────────
test("server ids: stable, game-scoped, never an internal id", () => {
  assert.equal(shortHash("1.2.3.4:28015"), shortHash("1.2.3.4:28015"));
  assert.match(externalServerId("rust", "1.2.3.4:28015"), /^rust-[0-9a-f]{10}$/);
  assert.notEqual(externalServerId("rust", "k"), nxeonServerId("rust", "k"));
  assert.deepEqual(parseServerId("rust-0123456789"), { game: "rust", hash: "0123456789" });
  assert.deepEqual(parseServerId("RUST-0123456789"), { game: "rust", hash: "0123456789" });
  for (const bad of ["notagame-0123456789", "rust-012345678", "rust-0123456789x", "rust", "../../x"]) assert.equal(parseServerId(bad), null, bad);
});

// ── facets + index rules ─────────────────────────────────────────────────
const d = (iso: string) => new Date(iso);
const ROWS: FacetRow[] = [
  { game: "rust", cc: "DE", n: 12, p: 400, newest: d("2026-10-04T00:00:00Z") },
  { game: "rust", cc: "fr", n: 3, p: 20, newest: d("2026-10-01T00:00:00Z") },
  { game: "rust", cc: "US", n: 9, p: 90, newest: d("2026-10-03T00:00:00Z") },
  { game: "rust", cc: null, n: 2, p: 0, newest: null },
  { game: "valheim", cc: "SG", n: 4, p: 7, newest: d("2026-09-20T00:00:00Z") },
];

test("rollUp: totals per game, country, continent; unknown country kept in game totals only", () => {
  const f = rollUp(ROWS);
  assert.equal(f.total.n, 30); assert.equal(f.total.p, 517);
  const r = f.games.get("rust")!;
  assert.equal(r.n, 26); assert.equal(r.unknown.n, 2);
  assert.equal(r.countries.get("FR")!.n, 3, "country codes upper-cased");
  assert.equal(r.continents.get("EU")!.n, 15);
  assert.equal(regionTally(f, "rust", { kind: "continent", code: "EU", slug: "europe", label: "Europe" }).n, 15);
  assert.equal(regionTally(f, "palworld", { kind: "continent", code: "EU", slug: "europe", label: "Europe" }).n, 0);
  assert.deepEqual(continentTabs(f, "rust").map((t) => t.region.slug), ["europe", "north-america"]);
  assert.deepEqual(topCountries(f, "rust", 2).map((t) => t.region.code), ["DE", "US"]);
  assert.deepEqual(topCountries(f, "rust", 5, "EU").map((t) => t.region.code), ["DE", "FR"]);
  assert.equal(r.newest, Date.parse("2026-10-04T00:00:00Z"));
});

test("indexable: thresholds, pagination, filters, server pages", () => {
  assert.equal(indexable({ kind: "home", listings: 0 }), true);
  assert.equal(indexable({ kind: "games", listings: 0 }), true);
  assert.equal(indexable({ kind: "game", listings: GAME_INDEX_MIN - 1 }), false);
  assert.equal(indexable({ kind: "game", listings: GAME_INDEX_MIN }), true);
  assert.equal(indexable({ kind: "game", listings: 0 }), false, "empty game pages render but are noindex");
  assert.equal(REGION_INDEX_MIN, 10);
  assert.equal(indexable({ kind: "region", listings: 9 }), false);
  assert.equal(indexable({ kind: "region", listings: 10 }), true);
  assert.equal(indexable({ kind: "region", listings: 500, page: 2 }), false);
  assert.equal(indexable({ kind: "game", listings: 500, filtered: true }), false);
  assert.equal(indexable({ kind: "home", listings: 500, filtered: true }), false);
  assert.equal(indexable({ kind: "server", listings: 1 }), false, "third-party detail pages are noindex");
  assert.equal(indexable({ kind: "server", listings: 1, nxeonHosted: true }), true);
});

test("canonical URLs: filters collapse to the base, page N keeps itself", () => {
  assert.equal(canonicalFor("/game-servers/directory/rust"), "/game-servers/directory/rust");
  assert.equal(canonicalFor("/game-servers/directory/rust", { page: 3 }), "/game-servers/directory/rust?page=3");
  assert.equal(canonicalFor("/game-servers/directory/rust", { page: 3, filtered: true }), "/game-servers/directory/rust");
  assert.equal(canonicalFor("/game-servers/directory/rust", { page: 1 }), "/game-servers/directory/rust");
});

test("copy states only numbers: no 'provider', no superlatives, empty states honest", () => {
  const f = rollUp(ROWS);
  const eu = { kind: "continent" as const, code: "EU" as const, slug: "europe", label: "Europe" };
  const de = { kind: "country" as const, code: "DE", slug: "germany", label: "Germany", continent: "EU" as const };
  const texts = [
    gameIntro("Rust", f, "rust"), gameIntro("Palworld", f, "palworld"), regionIntro("Rust", eu, regionTally(f, "rust", eu), f, "rust"),
    gameDescription("Rust", f.games.get("rust")!, 3), gameDescription("Palworld", { n: 0, p: 0, newest: 0 }, 0),
    regionDescription("Rust", de, regionTally(f, "rust", de)), ...regionFaq("Rust", de, regionTally(f, "rust", de), [{ name: "A", players: 5, max: 10 }]).flat(),
  ];
  for (const t of texts) {
    assert.ok(!/provider|best|great|friendly|active|#1|guarantee/i.test(t), t);
  }
  assert.match(gameIntro("Rust", f, "rust"), /^26 public Rust servers listed, with 517 players online at the last refresh\./);
  assert.match(gameIntro("Rust", f, "rust"), /Most are in Germany \(12\), United States \(9\), France \(3\)\./);
  assert.match(regionIntro("Rust", eu, regionTally(f, "rust", eu), f, "rust"), /15 public Rust servers listed in Europe.*58% of all listed Rust servers.*By country: Germany \(12\), France \(3\)/);
  assert.match(gameIntro("Palworld", f, "palworld"), /^No public Palworld servers are listed right now/);
  assert.equal(regionFaq("Rust", de, { n: 0, p: 0, newest: 0 }, []).length, 2, "no 'busiest server' answer without data");
});

test("nearestAlternatives: same continent countries first, never the page itself", () => {
  const f = rollUp(ROWS);
  const fr = { kind: "country" as const, code: "FR", slug: "france", label: "France", continent: "EU" as const };
  const alts = nearestAlternatives(f, "rust", fr).map((x) => x.region.slug);
  assert.deepEqual(alts, ["germany", "europe", "north-america"]);
});

test("structured data: ItemList positions, production URLs, at most 24; breadcrumb trail", () => {
  const items = Array.from({ length: 30 }, (_, i) => ({ name: `S${i}`, path: i % 2 ? `${DIR}/server/rust-000000000${i % 10}` : null }));
  const ld = itemListLd({ appUrl: "https://nxeon.cloud", name: "Rust servers", path: `${DIR}/rust`, total: 979, items }) as {
    "@type": string; url: string; mainEntity: { numberOfItems: number; itemListElement: { position: number; name: string; url?: string }[] };
  };
  assert.equal(ld["@type"], "CollectionPage");
  assert.equal(ld.url, "https://nxeon.cloud/game-servers/directory/rust");
  assert.equal(ld.mainEntity.numberOfItems, 979);
  assert.equal(ld.mainEntity.itemListElement.length, 24);
  assert.deepEqual(ld.mainEntity.itemListElement.map((e) => e.position), Array.from({ length: 24 }, (_, i) => i + 1));
  assert.ok(ld.mainEntity.itemListElement.every((e) => !e.url || e.url.startsWith("https://nxeon.cloud/")));
  assert.doesNotThrow(() => JSON.parse(JSON.stringify(ld)));
  const de = { kind: "country" as const, code: "DE", slug: "germany", label: "Germany", continent: "EU" as const };
  assert.deepEqual(trailFor("region", { game: "rust", gameName: "Rust", region: de }), [
    { name: "Server directory", path: DIR }, { name: "Rust", path: `${DIR}/rust` }, { name: "Germany", path: `${DIR}/rust/germany` },
  ]);
  assert.deepEqual(trailFor("games").map((t) => t.path), [DIR, `${DIR}/games`]);
});

test("sitemap paths: only indexable aggregate pages, with the newest listing date", () => {
