  assert.ok(ld.mainEntity.itemListElement.every((e) => !e.url || e.url.startsWith("https://nxeon.cloud/")));
  assert.doesNotThrow(() => JSON.parse(JSON.stringify(ld)));
  const de = { kind: "country" as const, code: "DE", slug: "germany", label: "Germany", continent: "EU" as const };
  assert.deepEqual(trailFor("region", { game: "rust", gameName: "Rust", region: de }), [
    { name: "Server directory", path: DIR }, { name: "Rust", path: `${DIR}/rust` }, { name: "Germany", path: `${DIR}/rust/germany` },
  ]);
