/**
 * Directory v2 SQL against a THROWAWAY Postgres (never the shared one). Skipped unless
 * DIRECTORY_TEST_DATABASE_URL is set, e.g.
 *   DIRECTORY_TEST_DATABASE_URL=postgresql://x@127.0.0.1:54399/dirhubtest npx tsx --test test/directory-hub-db.test.ts
 * after `DATABASE_URL=<that url> npx prisma db push --skip-generate`. Wipes ExternalServer + Setting in that DB.
 */
import test from "node:test";
import assert from "node:assert/strict";

const URL_ = process.env.DIRECTORY_TEST_DATABASE_URL;
const T = URL_ ? test : test.skip;
if (URL_) process.env.DATABASE_URL = URL_;

const NOW = Date.now();
const min = (n: number) => new Date(NOW - n * 60_000);

async function setup() {
  const { db } = await import("../lib/db");
  await db.externalServer.deleteMany();
  await db.setting.deleteMany();
  await db.setting.create({ data: { key: "directory_external_show", value: "true" } });
  const row = (i: number, o: Record<string, unknown> = {}) => ({
    source: "valve", sourceKey: `10.0.0.${i}:27015`, game: "rust", name: `Server ${String(i).padStart(2, "0")}`, host: `10.0.0.${i}`,
    ip: `10.0.0.${i}`, port: 27015, country: i % 2 ? "DE" : "us", players: i, maxPlayers: 50, connKey: `10.0.0.${i}:27015`, ipKey: `10.0.0.${i}:27015`,
    attribution: "steam", lastSeenAt: min(10), firstSeenAt: min(1000 - i), ...o,
  });
  const data = [
    ...Array.from({ length: 30 }, (_, i) => row(i + 1)),
    row(40, { hidden: true }), row(41, { blockedReason: "suffix" }), row(42, { probeStatus: "DEAD" }),
    row(43, { lastSeenAt: min(5 * 1440) }), // not seen for 5 days
    row(44, { lastSeenAt: min(180), name: "Stale count 100%_x" }), // seen 3 h ago: listed, count not fresh
    row(45, { game: "valheim", country: "SG" }),
  ];
  await db.externalServer.createMany({ data: data as never });
  const q = await import("../lib/directory-query");
  q.resetDirectoryCaches();
  return { db, q, sql: await import("../lib/directory-query-sql"), ids: await import("../lib/directory-ids") };
}

T("facets: only the public set is counted, players only when fresh", async () => {
  const { q } = await setup();
  const f = await q.directoryFacets();
  const rust = f.games.get("rust")!;
  assert.equal(rust.n, 31, "30 + the stale-count row; hidden/blocked/DEAD/5-day-old excluded");
  assert.equal(rust.p, (30 * 31) / 2, "the 3 h old row's 44 players are not 'now'");
  assert.equal(rust.countries.get("US")!.n, 15, "lower-case country codes upper-cased in SQL");
  assert.equal(f.games.get("valheim")!.continents.get("AS")!.n, 1);
});

T("pages: total via window count, offsets, sorting, filters, escaping", async () => {
  const { q } = await setup();
  const p1 = await q.listExternal({ game: "rust", page: 1 });
  assert.equal(p1.total, 31);
  assert.equal(p1.rows.length, 24);
  assert.equal(p1.rows[0].name, "Server 30", "most players first");
  const p2 = await q.listExternal({ game: "rust", page: 2 });
  assert.equal(p2.rows.length, 7);
  assert.equal(new Set([...p1.rows, ...p2.rows].map((r) => r.publicId)).size, 31, "no row on two pages");
  const de = await q.listExternal({ game: "rust", countries: ["DE"], page: 1 });
  assert.ok(de.rows.every((r) => r.country === "DE"));
  const has = await q.listExternal({ game: "rust", players: "has", page: 1 });
  assert.equal(has.total, 30, "stale count is not 'has players'");
  const newest = await q.listExternal({ game: "rust", sort: "newest", page: 1 });
  assert.equal(newest.rows[0].name, "Stale count 100%_x");
  const lit = await q.listExternal({ game: "rust", q: "100%_", page: 1 });
  assert.equal(lit.total, 1, "% and _ match literally");
  const none = await q.listExternal({ game: "rust", q: "%%", page: 1 });
  assert.equal(none.total, 0);
  const stale = (await q.listExternal({ game: "rust", q: "stale", page: 1 })).rows[0];
  assert.equal(stale.players, null, "a 3 h old count is not shown as playing now");
});

T("detail lookup: SQL sha256 id equals the JS id; non-public rows are not found", async () => {
  const { q, ids } = await setup();
  const id = ids.externalServerId("rust", "10.0.0.7:27015");
  const [game, hash] = [id.split("-")[0], id.split("-")[1]];
  const e = await q.findServer(game, hash);
  assert.equal(e?.name, "Server 07");
  assert.equal(e?.publicId, id);
  const hidden = ids.externalServerId("rust", "10.0.0.40:27015").split("-")[1];
  assert.equal(await q.findServer("rust", hidden), null);
  assert.equal(await q.findServer("valheim", hash), null, "id is game-scoped");
});

T("third-party listing switched off: nothing external anywhere", async () => {
  const { db, q } = await setup();
  await db.setting.update({ where: { key: "directory_external_show" }, data: { value: "false" } });
  q.resetDirectoryCaches();
  assert.equal((await q.directoryFacets()).total.n, 0);
  assert.equal((await q.listExternal({ game: "rust" })).total, 0);
});

