/**
 * Directory v2 rendering helpers (app/nxm/_data/directory-hub.ts) and the v1 layout composer
 * (app/nxm/_data/server-directory.ts legacyPage). Pure string rendering; no database is touched.
 */
import test from "node:test";
import assert from "node:assert/strict";
import { factualLine, hubCard, qs, readFilters } from "../app/nxm/_data/directory-hub";
import { legacyPage } from "../app/nxm/_data/server-directory";
import type { DirEntry } from "../lib/server-directory";

const entry = (o: Partial<DirEntry> = {}): DirEntry => ({
  key: "x-abc", source: "external", nxeon: false, game: "rust", name: "Plain", tagline: "", description: "", imageUrl: null,
  address: "1.2.3.4:28015", host: "1.2.3.4", port: 28015, alsoKeys: [], players: 12, maxPlayers: 100, country: "DE", region: null,
  featured: false, href: null, websiteUrl: null, seenAt: Date.parse("2026-10-05T09:00:00Z"), attribution: "steam", checkedAt: null,
  publicId: "rust-0123456789", map: "Procedural Map", ...o,
});

test("hubCard escapes every server-supplied value and links to the detail page", () => {
  const h = hubCard(entry({ name: `<img src=x onerror=alert(1)>"'`, map: "<script>", address: `1.2.3.4:28015"><b>` }));
  assert.ok(!/<img src=x/.test(h) && !/<script>/.test(h) && !/"><b>/.test(h), h);
  assert.match(h, /href="[^"]*\/game-servers\/directory\/server\/rust-0123456789"/);
  assert.match(h, /aria-label="Copy the address of /);
  assert.match(h, /12<\/b> \/ 100 playing/);
  assert.match(h, /Seen on the list 2026-10-05 09:00 UTC/, "no-probe wording, never 'Checked'");
  assert.ok(!/Checked/.test(h));
});

test("hubCard: stale count shows capacity, never a live figure", () => {
  const h = hubCard(entry({ players: null }));
  assert.match(h, /Up to 100 players/);
  assert.ok(!/playing/.test(h));
});

test("factualLine uses stored fields only", () => {
  assert.equal(factualLine({ game: "rust", country: "DE", map: "Barren", maxPlayers: 200 }), "Rust server in Germany. Map: Barren. 200 slots.");
  assert.equal(factualLine({ game: "valheim", country: null, map: null, maxPlayers: null }), "Valheim server.");
});

test("URL state: defaults dropped, unknown values ignored, stable key order", () => {
  const f = readFilters({ q: "  moose ", players: "has", sort: "bogus", page: "0" });
  assert.deepEqual(f, { q: "moose", players: "has", sort: "players", page: 1 });
  assert.equal(qs(f), "?q=moose&players=has");
  assert.equal(qs({ ...f, page: 3, sort: "newest" }, { region: "europe" }), "?region=europe&q=moose&players=has&sort=newest&page=3");
  assert.equal(qs(readFilters({})), "");
});

test("legacyPage (v1 layout): escapes plain slots, keeps :html slots, fails closed on a missing slot", () => {
  const keys = ["hero.chip", "hero.h1a", "hero.h1b", "hero.sub", "hero.ctas:html", "facts:html", "featured:html", "list.h", "list.lede", "games:html", "tools:html", "grid:html", "attribution:html", "steps.h", "steps.lede", "steps:html", "faq.lede", "faq:html", "final.h", "final.p", "final:html"];
  const slots = Object.fromEntries(keys.map((k) => [k, k.endsWith(":html") ? `<i>${k}</i>` : `<b>${k}</b>`]));
  const out = legacyPage(slots);
  assert.match(out, /<i>grid:html<\/i>/);
  assert.match(out, /&#60;b&#62;hero.h1a&#60;\/b&#62;/);
  assert.ok(!/<b>hero/.test(out));
  const { ["faq:html"]: _drop, ...missing } = slots;
  assert.throws(() => legacyPage(missing), /no value for slot "faq:html"/);
});

